comms.text:
@1 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְיִמְסְרִנוּן יְיָ אֱלָהָךְ בִּידָךְ וְתִשְׁבֵּי שִׁבְיְהוֹן:
@2 וְתֶחֱזֵי בְּשִׁבְיָה אִתְּתָא שַׁפִּירַת חֵזוּ וְתִתִּרְעֵי בַהּ וְתִסְבַהּ לָךְ לְאִנְתּוּ:
@3 וְתָעֵלִנַהּ לְגוֹ בֵיתָךְ וּתְגַלַח יָת רֵישַׁהּ וּתְרַבִּי יָת טוּפְרָנָהָא:
@4 וְתֶעְדֵי יָת כְּסוּת שִׁבְיַהּ מִנַהּ וְתֵיתַב בְּבֵיתָךְ וְתִבְכֵּי יָת אֲבוּהָא וְיָת אִמַהּ יְרַח יוֹמִין וּבָתַר כֵּן תֵּיעוּל לְוָתַהּ וְתִבְעֲלִנַהּ וּתְהֵי לָךְ לְאִנְתּוּ:
@5 וִיהֵי אִם לָא תִתִּרְעֵי בַהּ וְתִפְטְּרִנַהּ לְנַפְשַׁהּ וְזַבָּנָא לָא תְזַבְּנִנַהּ בְּכַסְפָּא לָא תִתָּגַר בַּהּ חֳלַף דִי עִינִיתַהּ:
@6 אֲרֵי תְהֶוְיָן לִגְבַר תַּרְתֵּין נְשִׁין חֲדָא רְחֶמְתָּא וַחֲדָא שְׂנִיאֲתָא וִילִידָן לֵהּ בְּנִין רְחֶמְתָּא וּשְׂנִיאֲתָא וִיהֵי בְּרָא בוּכְרָא לִשְׂנִיאֲתָא:
@7 וִיהֵי בְּיוֹמָא דְיַחְסֵן לִבְנוֹהִי יָת דִי יְהֵי לֵהּ לֵית לֵהּ רְשׁוּ לְבַכָּרָא יָת בַּר רְחֶמְתָּא עַל אַפֵּי בַר שְׂנִיאֲתָא בּוּכְרָא:
@8 אֲרֵי יָת בּוּכְרָא בַר שְׂנִיאֲתָא יַפְרַשׁ לְמִתַּן לֵהּ תַּרְתֵּין חָלָקִין בְּכֹל דִי יִשְׁתְּכַח לֵהּ אֲרֵי הוּא רֵישׁ תָּקְפֵּהּ לֵהּ חָזְיָא בְכֵרוּתָא:
@9 אֲרֵי יְהֵי לִגְבַר בַּר סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבַּל לְמֵימַר אֲבוּהִי וּלְמֵימַר אִמֵהּ וּמַלְפָן יָתֵהּ וְלָא יְקַבֵּל מִנְהוֹן:
@10 וְיֶחֱדוּן בֵּהּ אֲבוּהִי וְאִמֵּהּ וְיַפְּקוּן יָתֵהּ לָקֳדָם סָבֵי קַרְתֵּהּ וְלִתְרַע בֵּית דִין אַתְרֵהּ:
@11 וְיֵימְרוּן לְסָבֵי קַרְתֵּהּ בְּנָנָא דֵין סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבֵּל לְמֵימְרָנָא זָלֵל בְּסָר וְסָבֵי חֲמַר:
@12 וְיִרְגְמֻנֵהּ כָּל אֶנָשֵׁי קַרְתֵּהּ בְּאַבְנַיָא וִימוּת וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן:
@13 וַאֲרֵי יְהֵי בִגְבַר חוֹבַת דִין דִקְטוֹל וְיִתְקְטֵל וְתִצְלוֹב יָתֵהּ עַל צְלִיבָא:
@14 לָא תְבִית נְבִלְתֵּהּ עַל צְלִיבָא אֲרֵי מִקְבַּר תִּקְבְּרִנֵהּ בְּיוֹמָא הַהוּא אֲרֵי עַל דְחָב קֳדָם יְיָ אִצְטְלַב וְלָא תְסָאֵב יָת אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@15 לָא תֶחֱזֵי יָת תּוֹרָא דְאָחוּךְ אוֹ יַת אִמְרֵהּ דְטָעָן וְתִתְכְּבֵשׁ מִנְהוֹן אָתָבָא תָתֵבִנוּן לְאָחוּךְ:
@16 וְאִם לָא קָרֵב אֲחוּךְ לְוָתָךְ וְלָא יְדַעַתְּ לֵהּ וְתַכְנְשִׁנֵהּ לְגוֹ בֵיתָךְ וִיהֵי עִמָךְ עַד דְיִתְבַּע אֲחוּךְ יָתֵהּ וְתָתֵיבִנֵהּ לֵהּ:
@17 וְכֵן תַּעְבֵּד לַחֲמָרֵהּ וְכֵן תַּעְבֵּד לִכְסוּתֵהּ וְכֵן תַּעְבֵּד לְכָל אֲבֵדַת אֲחוּךְ דִי תֵיבַד מִנֵהּ וְתַשְׁכְּחִנַהּ לֵית לָךְ רְשׁוּ לְאִתְכַּסָאָה:
@18 לָא תֶחֱזֵי יָת חֲמָרָא דְאָחוּךְ אוֹ תוֹרֵהּ רָמָן בְּאָרְחָא וְתִתְכְּבֵשׁ מִנְהוֹן אֲקָמָא תְקִים עִמֵהּ:
@19 לָא יְהֵי תִקוּן זֵין דִגְבַר עַל אִתְּתָא וְלָא יְתַקֵן גְבַר בְּתִקוּנֵי אִתְּתָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ כָּל עָבֵד אִלֵין:
@20 אֲרֵי יְעָרַע קִנָא דְצִפְּרָא קֳדָמָךְ בְּאָרְחָא בְּכָל אִילָן אוֹ עַל אַרְעָא אֶפְרוֹחִין אוֹ בֵיעִין וְאִמָא רְבֵעָא עַל אֶפְרֹחִין אוֹ עַל בֵּיעִין לָא תִסַב אִמָא עַל בְּנַיָא:
@21 שַׁלָחָא תְשַׁלַח יָת אִמָא וְיָת בְּנַיָא תִּסַב לָךְ בְּדִיל דְיֵיטַב לָךְ וְתוֹרִיפךְ יוֹמִין:
@22 אֲרֵי תִבְנֵי בֵּיתָא חַדְתָּא וְתַעְבֵּד תְּיָקָא לְאִגְרָךְ וְלָא תְשַׁוִי חוֹבַת דִין דִקְטוֹל בְּבֵיתָךְ אֲרֵי יִפֵּל דְנָפֵל מִנֵהּ:
@23 לָא תִזְרַע כַּרְמָךְ עֵרוּבִין דִילְמָא תִסְתָּאַב דִמְעַת זַרְעָא דִי תִזְרַע וַעֲלָלַת כַּרְמָא:
@24 לָא תִרְדֵי בְתוֹרָא וּבַחֲמָרָא כַּחֲדָא:
@25 לָא תִלְבַּשּׁ שַׁעַטְנֵזָא עֲמַר וְכִתָּן מְחֻבַּר כַּחֲדָא:
@26 כְּרֻסְפְּדִין תַּעְבֶּד לָךְ עַל אַרְבַּע כַּנְפֵי כְסוּתָךְ דִי תְכַסֵי בַהּ:
@27 אֲרֵי יִסַב גְבַר אִתְּתָא וְיֵעוּל לְוָתַהּ וְיִסְנִנַהּ:
@28 וִישַׁוִי לַהּ תַּסְקוֹפֵי מִלִין וְיַפֵּק עֲלַהּ שׁוּם בִּישׁ וְיֵימַר יָת אִתְּתָא הָדָא נְסֵבִית וְעַלִית לְוָתַהּ וְלָא אַשְׁכָּחִית לַהּ בְּתוּלִין:
@29 וְיִסַב אֲבוּהָא (נ''א אֲבוּהִי) דְעוּלֶמְתָּא וְאִמַהּ וְיַפְּקוּן יָת בְּתוּלֵי עוּלֶמְתָּא לָקֳדָם סָבֵי קַרְתָּא לִתְרַע בֵּית דִין אַתְרָא:
@30 וְיֵימַר אֲבוּהָא דְעוּלֶמְתָּא לְסָבַיָא יָת בְּרַתִּי יְהָבִית לְגַבְרָא הָדֵין לְאִנְתּוּ וּסְנִנַהּ:
@31 וְהָא הוּא שַׁוִי תַּסְקוֹפֵי מִלִין לְמֵימַר לָא אַשְׁכָּחִית לִבְרַתָּךְ בְּתוּלִין וְאִלֵין בְּתוּלֵי בְרַתִּי וְיִפְרְסוּן שׁוֹשִׁיפָא קֳדָם סָבֵי קַרְתָּא:
@32 וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא יָת גַבְרָא וְיַלְקוּן יָתֵהּ:
@33 וְיִגְבּוּן מִנֵהּ מְאָה סִלְעִין דִכְסָף וְיִתְּנוּן לַאֲבוּהָא דְעוּלֶמְתָּא אֲרֵי אַפֵּק שׁוּם בִּישׁ עַל בְּתוּלְתָּא דְיִשְׂרָאֵל וְלֵהּ תְּהֵי לְאִנְתּוּ לֵית לֵהּ רְשׁוּ לְמִפְטְּרַהּ כָּל יוֹמוֹהִי:
@34 וְאִם קֻשְׁטָא הֲוָה פִּתְגָמָא הָדֵין לָא אִשְׁתְּכָחוּ בְתוּלִין לְעוּלֶמְתָּא:
@35 וְיַפְּקוּן יָת עוּלֶמְתָּא לִתְרַע בֵּית אָבוּהָא וְיִרְגְמֻנַהּ אֱנָשֵׁי קַרְתַּהּ בְּאַבְנַיָא וּתְמוּת אֲרֵי עָבְדַת קְלָנָא בְּיִשְׂרָאֵל לְזַנָאָה בֵּית אֲבוּהָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@36 אֲרֵי יִשְׁתְּכַח גְבַר דְשָׁכֵב עִם אִתְּתָא אִתַּת גְבַר וְיִתְקַטְלוּן אַף תַּרְוֵיהוֹן גַבְרָא דְשָׁכֵב עִם אִתְּתָא וְאִתְּתָא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@37 אֲרֵי תְהֵי עוּלֶמְתָּא בְתֻלְתָּא דִמְאָרְסָא לִגְבַר וְיַשְׁכְּחִנַהּ גְבַר בְּקַרְתָּא וְיִשְׁכּוּב עִמַהּ:
@38 וְתַפְּקוּן יָת תַּרְוֵיהוֹן לִתְרַע קַרְתָּא הַהִיא וְתִרְגְמוּן יָתְהוֹן בְּאַבְנַיָא וִימוּתוּן יָת עוּלֶמְתָּא עַל עֵסַק דִי לָא צְוָחַת בְּקַרְתָּא וְיָת גַבְרָא עַל עֵסַק דְעַנִי יָת אִתַּת חַבְרֵהּ וּתְפַלֵי עָבֵד דְבִּישׁ מִבֵּינָךְ:
@39 וְאִם בְּחַקְלָא יַשְׁכַּח גְבַר יָת עוּלֶמְתָּא דִמְאָרְסָא וְיִתְקֶף בַּהּ גַבְרָא וְיִשְׁכּוּב עִמַהּ וְיִתְקְטֵּל גַבְרָא דְשָׁכֵב עִמַהּ בִּלְחוֹדוֹהִי:
@40 וּלְעוּלֶמְתָּא לָא תַעְבֵּד מִדַעַם לֵית לְעוּלֶמְתָּא חוֹבַת דִין דִקְטוֹל אֲרֵי כְּמָא דִיקוּם גַבְרָא עַל חַבְרֵהּ וְיִקְטְּלִנֵהּ נְפַשׁ כֵּן פִּתְגָמָא הָדֵין:
@41 אֲרֵי בְחַקְלָא אַשְׁכְּחַהּ צְוָחַת עוּלֶמְתָּא דִמְאָרְסָא וְלֵית דְפָרִיק לַהּ:
@42 אֲרֵי יַשְׁכַּח גְבַר עוּלֶמְתָּא בְתֻלְתָּא דִי לָא מְאָרְסָא וְיֶחֱדִנַהּ וְיִשְׁכּוּב עִמַהּ וְיִשְׁתַּכְּחוּן:
@43 וְיִתֵּן גַבְרָא דְיִשְׁכֻּב עִמַהּ לַאֲבוּהָא דְעוּלֶמְתָּא חַמְשִׁין סִלְעִין דִכְסַף וְלֵהּ תְּהֵי לְאִנְתּוּ חֳלַף דִי עַנְיַהּ לֵית לֵהּ רְשׁוּ לְמִפְטְרַהּ כָּל יוֹמוֹהִי:
@44 לָא יִסַב גְבַר יָת אִתַּת אֲבוּהִי וְלָא יְגַלֵי כַּנְפָא דַאֲבוּהִי:
@45 לָא יִדְכֵּי דְפָסִיק וְדִמְחַבַּל לְמֵעַל בִּקְהָלָא דַיְיָ:
@46 לָא יִדְכֵּי מַמְזֵרָא לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לֵהּ לְמֵעַל בִּקְהָלָא דַיְיָ:
@47 לָא יִדְכּוּן עַמוֹנָאֵי וּמוֹאָבָאֵי לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָא דַיְיָ עַד עָלָם:
@48 עַל עֵסַק דִי לָא עֲרָעוּ יָתְכוֹן בְּלַחְמָא וּבְמַיָא בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם וְדִי אֲגַר עֲלָךְ יָת בִּלְעָם בַּר בְּעוֹר מִפְּתוֹר אֲרַם דִי עַל פְּרָת לְלַטָּיוּתָךְ:
@49 וְלָא אָבֵי יְיָ אֱלָהָךְ לְקַבָּלָא מִן בִּלְעָם וַהֲפַךְ יְיָ אֱלָהָךְ לָךְ יָת לְוָטִין לְבִרְכָן אֲרֵי רָחֲמָךְ יְיָ אֱלָהָךְ:
@50 לָא תִתְבַּע שְׁלָמְהוֹן וְטָבָתְהוֹן כָּל יוֹמָיךְ לְעָלָם:
@51 לָא תְרַחַק אֱדוֹמָאָה אֲרֵי אֲחוּךְ הוּא לָּא תְרַחַק מִצְרָאָה אֲרֵי דַיָר הֲוֵיתָא בְאַרְעֵהּ:
@52 בְּנִין דִי יִתְיְלִידוּ לְהוֹן דָרָא תְלִיתָאָה יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָה דַיְיָ:
@53 אֲרֵי תִפּוֹק מַשְׁרִיתָא עַל בַּעֲלֵי דְבָבָךְ וְתִסְתַּמַר מִכֹּל מִדַעַם בִּישׁ:
@54 אֲרֵי יְהֵי בָךְ גְבַר דִי לָא יְהֵּי דְכֵי מִקְרֵהּ לֵילְיָא וְיִפּוֹק לְמִבָּרָא לְמַשְׁרִיתָא לָא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@55 וִיהֵי לְמִפְנֵי רַמְשָׁא יַסְחֵי בְמַיָא וּכְמֵעַל שִׁמְשָׁא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@56 וַאֲתַר מְתַקֵן יְהֵי לָךְ מִבָּרָא לְמַשְׁרִיתָא וְתִפּוֹק תַּמָן לְבָרָא:
@57 וְסִכְּתָא תְּהֵי לָךְ עַל זֵינָךְ וִיהֵי בְּמִיתְבָךְ לְבָרָא וְתַחְפַּר בַּהּ וּתְתוּב וּתְכַסֵי יָת מִפְּקָתָךְ:
@58 אֲרֵי יְיָ אֱלָהָךְ שְׁכִינְתֵּהּ מְהַלְכָא בְּגוֹ מַשְׁרִיתָךְ לְשֵׁזָבוּתָךְ וּלְמִמְסַר בַּעֲלֵי דְבָבָךְ קֳדָמָךְ וּתְהֵי מַשְׁרִיתָךְ קַדִישָׁא וִלָא יִתְחֲזֵי בָךְ עֲבֵרַת פִּתְגָם וִיתוּב מֵימְרֵהּ מִלְאוֹטָבָא לָךְ:
@59 לָא תִמְסַר עֶבֶד עַמְמִין לְיַד רִבּוֹנֵהּ דְיִשְׁתֵּזֵב לְוָתָךְ מִלְוָת רִבּוֹנֵהּ:
@60 עִמָךְ יִתֵּב בֵּינָךְ בְּאַתְרָא דִי יִתִּרְעֵי בַּחֲדָא מִן קִרְוָיךְ בִּדְיֵיטַּב לֵהּ לָא תוֹנִנֵהּ:
@61 לָא תְהֵי אִתְּתָא מִבְּנַת יִשְׂרָאֵל לִגְבָר עָבֵד וְלָא יִסַב גַבְרָא מִבְּנֵי יִשְׂרָאֵל אִתְּתָא אָמָא:
@62 לָא תָעֵל אֲגַר זַנִיתָא וְחוּלְפַן כַּלְבָא לְבֵית מַקְדְשָׁא דַיְיָ אֱלָהָךְ לְכָל נִדְרָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ אַף תַּרְוֵיהוֹן:
@63 לָא תְרַבֵּי לַאֲחוּךְ רִבִּית כְּסַף רִבִּית עִבוּר רִבִּית כָּל מִדַעַם דְמִתְרַבֵּי:
@64 לְבַר עַמְמִין תְּרַבֵּי וְלַאֲחוּךְ לָא תְרַבֵּי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל אוֹשָׁטוּת יְדָךְ עַל אַרְעָא דִי אַתְּ עָלֵל:לתַמָן לְמֵירְתַהּ:
@65 אֲרֵי תִדַר נְדַר קֳדָם יְיָ אֱלָהָךְ לָא תְאַחַר לְשַׁלָמוּתֵהּ אֲרֵי מִתְבַּע יִתְבְּעִנֵהּ יְיָ אֱלָהָךְ מִנָךְ וִיהֵי בָךְ חוֹבָא:
@66 וַאֲרֵי תִתִּמְנַע לְמִנְדַר לָא יְהֵי בָךְ חוֹבָא:
@67 אַפָּקוּת סִפְוָתָךְ תִּטַר וְתַעְבֵּד כְּמָא דִי נְדַרְתָּא קֳדָם יְיָ אֱלָהָךְ נְדַבְתָּא דִי מַלֶלְתָּא בְּפוּמָךְ:
@68 אֲרֵי תִתָּגַר בְּכַרְמָא דְחַבְרָךְ וְתֵיכוּל עִנְבִין כְּנַפְשָׁךְ שִׂבְעָךְ וּלְמָאנָךְ לָא תִתֵּן:
@69 אֲרֵי תִתָּגַר בְּקַמְתָא דְחַבְרָךְ וְתִקְטוֹף מְלִילָן בִּידָךְ וּמַגְלָא לָא תְרִים עַל קַמְתָא דְחַבְרָךְ:
@70 אֲרֵי יִסַב גְבַר אִתְּתָא וְיִבְעֲלִנַהּ וִיהֵי אִם לָא תַשְׁכַּח רַחֲמִין בְּעֵינוֹהִי אֲרֵי אַשְׁכַּח בַּהּ עֲבֵרַת פִתְגָם וְיִכְתּוֹב לַהּ גֵט פִּטוּרִין וִיהַב בִּידַהּ וְיִפְטְּרִנַהּ מִבֵּיתֵהּ:
@71 וְתִפּוֹק מִבֵּיתֵהּ וּתְהַךְ וּתְהֵי לִגְבַר אָחֳרָן:
@72 וְיִסְנִנַהּ גַבְרָא בַתְרָאָה וְיִכְתּוֹב לַהּ גֵטּ פִטּוּרִין וְיִתֵּן בִּידַהּ וְיִפְטְרִנַהּ מִבֵּיתֵהּ אוֹ אֲרֵי יְמוּת גַבְרָא בַתְרָאָה דְנָסְבַהּ לֵה לְאִנְתּוּ:
@73 לֵית לֵהּ רְשׁוּ לְבַעֲלַהּ קַדְמָאָה דִי פָטְרַהּ לְמִתֻּב לְמִסְבַהּ לְמֶהֱוֵי לֵה לְאִנְתּוּ בָּתַר דִי אִסְתָּאָבַת אֲרֵי מְרָחָקָא הִיא קֳדָם יְיָ וְלָא תְחַיַב יָת אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@74 אֲרֵי יִסַב גְבַר אִתְּתָא חַדְתָּא לָא יִפּוֹק בְּחֵילָא וְלָא יֵעִבַר עֲלוֹהִי לְכָל מִדָעַם פָּנֵי יְהֵי לְבֵיתֵהּ שַׁתָּא חֲדָא וְיַחְדֵי יָת אִתְּתֵהּ דִי נְסַב:
@75 לָא יִסַב מַשְׁכּוֹנָא רֵחַיָא וְרִכְבָּא אֲרֵי בְהוֹן מִתְעֲבֵד מָזוֹן לְכָל נְפַשׁ:
@76 אֲרֵי יִשְׁתְּכַח גְבַר גָנֵב נַפְשָׁא מֵאֲחוֹהִי מִבְּנֵי יִשְׂרָאֵל וְיִתָּגַר בֵּהּ וִיזַבְּנִנֵהּ וְיִתְקְטֵל גַנָבָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@77 אִסְתַּמַר בְּמַכְתַּשׁ סְגִירוּ לְמִטַּר לַחֲדָא וּלְמֶעְבָּד כְּכֹל דִי יַלְפוּן יָתְכוֹן כָּהֲנַיָא לֵוָאֵי כְּמָא דִי פַקֶדְתִּנוּן תִּטְרוּן לְמֶעְבָּד:
@78 הֱוֵי דְכִיר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְמִרְיָם בְּאָרְחָא בְּמִפָקְכוֹן מִמִצְרָיִם:
@79 אֲרֵי תַרְשֵׁי בְחַבְרָךְ רְשׁוּ מִדָעַם לָא תֵעוּל לְבֵיתֵהּ לְמִסַב מַשְׁכּוֹנֵהּ:
@80 בְּבָרָא תְּקוּם וְגַבְרָא דִי אַתְּ רָשֵׁי בֵהּ יַפֵק לְוָתָךְ יָת מַשְׁכּוֹנָא לְבָרָא:
@81 וְאִם גְבַר מִסְכֵּן הוּא לָא תִשְׁכּוּב בְּמַשְׁכּוֹנֵהּ:
@82 אָתָבָא תָתֵב לֵהּ יָת מַשְׁכּוֹנָא כְּמֵעַל שִׁמְשָׁא וְיִשְׁכּוּב בִּכְסוּתֵהּ וִיבָרֵכִנָךְ וְלָךְ תְּהֵי זְכוּתָא קֳדָם יְיָ אֱלָהָךְ:
@83 לָא תַעֲשׁוֹק אֲגִירָא עַנְיָא וּמִסְכֵּנָא מֵאַחָיךְ אוֹ מִגִיוֹרָךְ דִי בְאַרְעָךְ בְּקִרְוָיךְ:
@84 בְּיוֹמֵהּ תִּתֵּן אַגְרֵהּ וְלָא תֵעוּל עֲלוֹהִי שִׁמְשָׁא אֲרֵי עַנְיָא הוּא וְלֵהּ הוּא מְסַר יָת נַפְשֵׁהּ וְלָא יִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@85 לָא יְמוּתוּן אֲבָהָן עַל פּוּם בְּנִין וּבְנִין לָא יְמוּתוּן עַל פּוּם אֲבָהָן אֱנַשׁ בְּחוֹבֵהּ יְמוּתוּן:
@86 לָא תַצְלֵי דִין גִיוֹרָא וְיִתַּמָא וְלָא תִסַב מַשְׁכּוֹנָא לְבוּשׁ אַרְמְלָא:
@87 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ מִתַּמָן עַל כֵּן אֲנָא מְפַקְדָךְ לְמֶעְבַּד יָת פִּתְגָמָא הָדֵין:
@88 אֲרֵי תַחְצוֹד חֲצָדָךְ בְּחַקְלָךְ וְתִנְשֵׁי עֻמְרָא בְחַקְלָא לָא תְתוּב לְמִסְבֵהּ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ:
@89 אֲרֵי תַחְבּוֹט זֵיתָךְ לָא תְפַלֵי בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@90 אֲרֵי תִקְטוֹף כַּרְמָךְ לָא תְעָלֵל בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@91 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרָיִם עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵעְבַּד יָת פִּתְגָמָא הָדֵין:
@92 אֲרֵי יְהֵי דִין בֵּין גֻבְרַיָא וְיִתְקָרְבוּן לְדִינָא וִידוּנֻנוּן וִיזַכּוּן יָת זַכָּאָה וִיחַיְבוּן יָת חַיָבָא:
@93 וִיהֵי אִם בַּר חַיָבָא לְאַלְקָאָה חַיָבָא וְיִרְמִנֵהּ דַיָנָא וְיַלְקִנֵהּ קֳדָמוֹהִי כְּמִסַת חוֹבְתֵהּ בְּמִנְיָן:
@94 אַרְבְּעִין יַלְקִנֵהּ לָא יוֹסֵף דִילְמָא יוֹסֵף לְאַלְקָיוּתֵהּ עַל אִלֵין מָחָא רַבָּא וְיֵקַל אֲחוּךְ לְעֵינָיךְ:
@95 לָא תֵחוֹד פּוּם תּוֹרָא בִּדְיָשֵׁהּ:
@96 אֲרֵי יֵתְבוּן אַחִין כַּחֲדָא וִימוּת חַד מִנְהוֹן וּבַר לֵית לֵהּ לָא תְהֵי אִתַּת מֵתָנָא לְבָרָא לִגְבַר אוֹחֲרָן יְבָמַהּ יֵעוּל עֲלַהּ וְיִסְבַהּ לֵהּ לְאִנְתּוּ וְיִבְּמַהּ:
@97 וִיהֵי בּוּכְרָא דִי תְלִיד יְקוּם עַל שְׁמָא דַאֲחוּהִי מֵתָנָא וְלָא יִתִּמְחֵי שְׁמֵהּ מִיִשְׂרָאֵל:
@98 וְאִם לָא יִצְבֵי גַבְרָא לְמִסַב יָת יְבִמְתֵּהּ וְתִסַק יְבִמְתֵהּ לִתְרַע בֵּית דִינָא לָקֳדָם סָבַיָא וְתֵימַר לָא צָבֵי יְבָמִי לַאֲקָמָא לַאֲחוּהִי שְׁמָא בְּיִשְׂרָאֵל לָא אָבֵי לְיַבָּמוּתִי:
@99 וִיקְרוּן לֵהּ סָבֵי קַרְתֵּהּ וִימַלְלוּן עִמֵהּ וִיקוּם וְיֵימַר לָא רְעֵנָא לְמִסְבַהּ:
@100 וְתִתְקְרַב יְבִמְתֵּהּ לְוָתֵה לָקֳדָם סָבַיָא וְתַשְׁרֵי סֵינֵהּ מֵעַל רַגְלֵהּ וְתֵרוֹק בְּאַנְפּוֹהִי וְתָתֵב וְתֵימַר כְּדֵין יִתְעֲבֵד לִגְבַר דִי לָא יִבְנֵי יָת בֵּיתָא דַאֲחוּהִי:
@101 וְיִתְקְרֵי שְׁמֵהּ בְּיִשְׂרָאֵל בֵּית שְׁרִי סֵינָא:
@102 אֲרֵי יִנְצוּן גֻבְרִין כַּחֲדָא גְבַר וַאֲחוּהִי וְתִתְקְרֵב אִתַּת חַד לְשֵׁזָבָא יָת בַּעֲלַהּ מִיַד מָחוּהִי וְתוֹשֵׁט יְדַהּ וְתִתְקֵף בְּבֵית בַּהֲתְּתֵהּ:
@103 וּתְקוּץ יָת יְדַהּ לָא תְחוּס עֵינָךְ:
@104 לָא יְהֵי לָךְ בְּכִיסָךְ מַתְקַל וּמַתְקָל רַבְּתָא וּזְעֶרְתָּא:
@105 לָא יְהֵי לָךְ בְּבֵיתָךְ מְכִילָא וּמְכִילָא רַבְּתָא וּזְעֶרְתָּא:
@106 מַתְקִלִין שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ מְכִילָן שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@107 אֲרֵי מְרָחָק קֳדָם יְיָ אֱלהָךְ כָּל עָבֵד אִלֵין כֹּל עָבֵד שְׁקַר:
@108 הֲוֵי דְכִיר יָת דִי עֲבַד לָךְ עֲמָלֵק בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם:
@109 דִי עָרְעָךְ בְּאָרְחָא וְקָטֵל בָּךְ כָּל דַהֲווֹ מִתְאַחֲרִין בַּתְרָךְ וְאַתְּ מְשַׁלְהֵי וְלָאֵי וְלָא דָחֵיל מִן קֳדָם יְיָ:
@110 וִיהֵי כַּד יְנִיחַ יְיָ אֱלָהָךְ לָךְ מִכָּל בַּעֲלֵי דְבָבָךְ מִסְחוֹר סְחוֹר בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ תִּמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא לָא תִּתִּנְשֵׁי: פפפ:

@1 **כי תצא למלחמה.** במלחמת הרשות הכתוב מדבר, שבמלחמת ארץ ישראל אין לומר ושבית שביו, שהרי כבר נאמר (לעיל כ, טז) לא תחיה כל נשמה: **ושבית שביו.** לרבות כנענים שבתוכה ואף על פי שהם משבעה אמות:
@2 **אשת.** אפלו אשת איש: **ולקחת לך לאשה.** לא דברה תורה אלא כנגד יצר הרע. שאם אין הקדוש ברוך הוא מתירה, ישאנה באסור. אבל אם נשאה, סופו להיות שונאה, שנאמר אחריו (פסוק טו) כי תהיין לאיש וגו' וסופו להוליד ממנה בן סורר ומורה, לכך נסמכו פרשיות הללו:
@3 **ועשתה את צפרניה.** תגדלם כדי שתתנול:
@4 **והסירה את שמלת שביה.** לפי שהם נאים, שהגוים בנותיהם מתקשטות במלחמה בשביל להזנות אחרים עמהם: **וישבה בביתך.** בבית שמשתמש בו, נכנס ונתקל בה, יוצא ונתקל בה, רואה בבכייתה, רואה בנוולה, כדי שתתגנה עליו: **ובכתה את אביה.** כל כך למה, כדי שתהא בת ישראל שמחה וזו עצבה, בת ישראל מתקשטת וזו מתנולת:
@5 **והיה אם לא חפצת בה.** הכתוב מבשרך שסופך לשנאותה: **לא תתעמר בה.** לא תשתמש בה, בלשון פרסי קורין לעבדות ושמוש, עימראה. מיסודו של רבי משה הדרשן למדתי כן:
@8 **פי שנים.** כנגד שני אחים: **בכל אשר ימצא לו.** מכאן שאין הבכור נוטל פי שנים בראוי לבא לאחר מיתת האב, כבמחזק:
@9 **סורר.** סר מן הדרך: **ומורה.** מסרב בדברי אביו, לשון ממרים: **ויסרו אותו.** מתרין בו בפני שלשה ומלקין אותו. בן סורר ומורה אינו חיב, עד שיגנוב ויאכל תרטימר בשר וישתה חצי לוג יין. שנאמר (פסוק כ) זולל וסבא, ונאמר (משלי כג, כ) אל תהי בסובאי יין בזוללי בשר למו. ובן סורר ומורה נהרג על שם סופו, הגיעה תורה לסוף דעתו, סוף שמכלה ממון אביו ומבקש למודו ואינו מוצא, ועומד בפרשת דרכים ומלסטם את הבריות, אמרה תורה ימות זכאי ואל ימות חיב:
@12 **וכל ישראל ישמעו ויראו.** מכאן שצריך הכרזה בבית דין, פלוני נסקל על שהיה בן סורר ומורה:
@13 **וכי יהיה באיש חטא משפט מות.** סמיכות הפרשיות מגיד, שאם חסים עליו אביו ואמו, סוף שיצא לתרבות רעה ויעבור עברות ויתחיב מיתה בבית דין: **ותלית אתו על עץ.** רבותינו אמרו, כל הנסקלין, נתלין, שנאמר (פסוק כג) כי קללת אלהים תלוי. והמברך ה', בסקילה:
@14 **כי קללת אלהים תלוי.** זלזולו של מלך הוא, שאדם עשוי בדמות דיקנו וישראל הם בניו. משל לשני אחים תאומים שהיו דומין זה לזה, אחד נעשה מלך, ואחד נתפס ללסטיות ונתלה, כל הרואה אותו אומר המלך תלוי. כל קללה שבמקרא לשון הקל וזלזול, כמו (מלכ' א' ב, ח) והוא קללני קללה נמרצת:
@15 **והתעלמת.** כובש עין כאלו אינו רואהו: **לא תראה' והתעלמת.** לא תראה אותו שתתעלם ממנו, זהו פשוטו. ורבותינו אמרו פעמים שאתה מתעלם וכו' :
@16 **עד דרש אחיך.** וכי תעלה על דעתך שיתנהו לו קודם שידרשהו, אלא דרשהו שלא יהא רמאי: **והשבתו לו.** שתהא בו השבה, שלא יאכל בביתך כדי דמיו ותתבעם ממנו. מכאן אמרו, כל דבר שעושה ואוכל יעשה ויאכל, ושאינו עושה ואוכל, ימכר:
@17 **לא תוכל להתעלם.** לכבוש עינך כאלו אינך רואה אותו:
@18 **הקם תקים.** זו טעינה. להטעין משאוי שנפל מעליו: **עמו.** עם בעליו, אבל אם הלך וישב לו, ואמר לו הואיל ועליך מצוה אם רצית לטעון טעון, פטור:
@19 **לא יהיה כלי גבר על אשה.** שתהא דומה לאיש כדי שתלך בין האנשים, שאין זו אלא לשם ניאוף: **ולא ילבש גבר שמלת אשה.** לילך ולישב בין הנשים. דבר אחר שלא ישיר שער הערוה ושער של בית השחי: **כי תועבת.** לא אסרה תורה אלא לבוש המביא לידי תועבה:
@20 **כי יקרא.** פרט למזמן: **לא תקח האם.** בעודה על בניה:
@21 **למען ייטב לך.** אם מצוה קלה שאין בה חסרון כיס, אמרה תורה למען ייטב לך והארכת ימים, קל וחמר למתן שכרן של מצות חמורות:
@22 **כי תבנה בית חדש.** אם קימת מצות שלוח הקן סופך לבנות בית חדש ותקיים מצות מעקה, שמצוה גוררת מצוה, ותגיע לכרם ושדה ולבגדים נאים. לכך נסמכו פרשיות הללו: **מעקה.** גדר סביב לגג, ואונקלוס תרגם תיקא כעין תיק שמשמר מה שבתוכו: **כי יפל הנפל.** ראוי זה לפול ואף על פי כן לא תתגלגל מיתתו על ידך, שמגלגלין זכות על ידי זכאי וחובה על ידי חיב:
@23 **כלאים.** חטה ושעורה וחרצן במפלת יד: **פן תקדש.** כתרגומו תסתאב. כל דבר הנתעב על האדם, בין לשבח כגון הקדש, בין לגנאי כגון אסור, נופל בו לשון קדש, כמו (ישעיה סה, ה) אל תגש בי כי קדשתיך: **המלאה.** זה מלוי ותוספת שהזרע מוסיף:
@24 **לא תחרש בשור ובחמור.** הוא הדין לכל שני מינים שבעולם, והוא הדין להנהיגם יחד קשורים זוגים בהולכת שום משא:
@25 **שעטנז.** לשון ערוב. ורבותינו פרשו שוע טווי ונווז:
@26 **גדלים תעשה לך.** אף מן הכלאים. לכך סמכן הכתוב:
@27 **ובא אליה ושנאה.** סופו:
@28 **ושם לה עלילת דברים.** עברה גוררת עברה, עבר על לא תשנא (ויקרא יט, יז) סופו לבא לידי לשון הרע: **את האשה הזאת.** מכאן שאין אומר דבר אלא בפני בעל דין:
@29 **אבי הנערה ואמה.** מי שגדלו גדולים הרעים יתבזו עליה:
@30 **ואמר אבי הנערה.** מלמד שאין רשות לאשה לדבר בפני האיש:
@31 **ופרשו השמלה.** הרי זה משל, מחורין הדברים כשמלה:
@32 **ויסרו אתו.** מלקות:
@34 **ואם אמת היה הדבר.** בעדים והתראה שזנתה לאחר ארוסין:
@35 **אל פתח בית אביה.** ראו גדולים שגדלתם: **וסקלוה אנשי עירה.** במעמד כל אנשי עירה: **לזנות בית אביה.** כמו בבית אביה:
@36 **ומתו גם שניהם.** להוציא מעשה חדודים שאין האשה נהנית מהם: **גם.** לרבות הבאים מאחריהם. דבר אחר גם שניהם לרבות את הולד, שאם היתה מעברת אין ממתינין לה עד שתלד:
@37 **ומצאה איש בעיר.** לפיכך שכב עמה, פרצה קוראה לגנב. הא אלו ישבה בביתה לא אירע לה:
@40 **כי כאשר יקום** וגו' **.** לפי פשוטו זהו משמעו, כי אנוסה היא ובחזקה עמד עליה כאדם העומד על חברו להרגו. ורבותינו דרשו בו הרי זה בא ללמד ונמצא למד וכו' :
@44 **לא יקח.** אין לו בה לקוחין ואין קדושין תופסין בה: **ולא יגלה כנף אביו.** שומרת יבם של אביו הראויה לאביו. והרי כבר הזהר עליה משום (ויקרא יח, יד) ערות אחי אביך, אלא לעבור על זו בשני לאוין ולסמוך לה (פסוק ג) לא יבא ממזר, ללמד שאין ממזר אלא מחיבי כריתות וקל וחמר מחיבי מיתות בית דין, שאין בעריות מיתת בית דין שאין בה כרת:
@45 **פצוע דכא.** שנפצעו או שנדכאו ביצים שלו: **וכרות שפכה.** שנכרת הגיד ושוב אינו יורה קלוח זרע אלא שופך ושותת ואינו מוליד:
@46 **לא יבא ממזר בקהל ה'.** לא ישא ישראלית:
@47 **לא יבא עמוני.** לא ישא ישראלית:
@48 **על דבר.** על העצה שיעצו אתכם להחטיאכם: **בדרך.** כשהייתם בטרוף:
@50 **לא תדרש שלמם.** מכלל שנאמר (פסוק יז) עמך ישב בקרבך יכול אף זה כן, תלמוד לומר לא תדרש שלמם:
@51 **לא תתעב אדמי.** לגמרי ואף על פי שראוי לך לתעבו שיצא בחרב לקראתך: **לא תתעב מצרי.** מכל וכל, אף על פי שזרקו זכוריכם ליאור. מה טעם, שהיו לכם אכסניא בשעת הדחק. לפיכך. ט **בנים אשר יולדו להם דור שלישי.** ושאר האמות מתרין מיד. הא למדת שהמחטיא לאדם קשה לו מן ההורגו, שההורגו הורגו בעולם הזה, והמחטיאו מוציאו מן העולם הזה ומן העולם הבא, לפיכך אדום שקדמם בחרב לא נתעב וכן מצרים שטבעום, ואלו שהחטיאום נתעבו:
@53 **כי תצא** וגו' **ונשמרת.** שהשטן מקטרג בשעת הסכנה:
@54 **מקרה לילה.** דבר הכתוב בהוה: **ויצא אל מחוץ למחנה.** זו מצות עשה: **לא יבא אל תוך המחנה.** זו מצות לא תעשה. ואסור לכנס למחנה לויה, וכל שכן למחנה שכינה:
@55 **והיה לפנות ערב.** סמוך להערב שמשו יטבול, שאינו טהור בלא הערב שמש:
@56 **ויד תהיה לך.** כתרגומו ואתר, כמו (במדבר ב, יז) איש על ידו: **מחוץ למחנה.** חוץ לענן:
@57 **על אזנך.** לבד משאר כלי תשמישך: **אזנך.** כמו כלי זינך:
@58 **ולא יראה בך.** הקדוש ברוך הוא ערות דבר:
@59 **לא תסגיר עבד.** כתרגומו. דבר אחר אפלו עבד כנעני של ישראל שברח מחוצה לארץ לארץ ישראל:
@61 **לא תהיה קדשה.** מפקרת, מקדשת ומזמנת לזנות: **ולא יהיה קדש.** מזמן למשכב זכור. ואונקלוס תרגם לא תהי אתתא מבנת ישראל לגבר עבד, שאף זו מפקרת לבעילת זנות היא, מאחר שאין קדושין תופסין לו בה, שהרי הקשו לחמור, שנאמר (בראשית כב, ה) שבו לכם פה עם החמור, עם הדומה לחמור. ולא יסב גברא מבני ישראל אתתא אמא, שאף הוא נעשה קדש על ידה, שכל בעילותיו בעילות זנות שאין קדושין תופסין לו בה:
@62 **אתנן זונה.** נתן לה טלה באתננה פסול להקרבה: **ומחיר כלב.** החליף שה בכלב: **גם שניהם.** לרבות שנוייהם, כגון חטים ועשאן סלת:
@63 **לא תשיך.** אזהרה ללוה שלא יתן רבית למלוה, ואחר כך אזהרה למלוה (ויקרא כה, לז) את כספך לא תתן לו בנשך:
@64 **לנכרי תשיך.** ולא לאחיך. לאו הבא מכלל עשה, עשה, לעבור עליו בשני לאוין ועשה:
@65 **לא תאחר לשלמו.** שלשה רגלים. ולמדוהו רבותינו מן המקרא:
@67 **מוצא שפתיך תשמר ועשית.** לתן עשה על לא תעשה:
@68 **כי תבא בכרם רעך.** בפועל הכתוב מדבר: **כנפשך.** כמה שתרצה: **שבעך.** ולא אכילה גסה: **ואל כליך לא תתן.** מכאן שלא דברה תורה אלא בשעת הבציר, בזמן שאתה נותן לכליו של בעל הבית, אבל אם שכרו לעדור ולקשקש, אינו אוכל:
@69 **כי תבא בקמת רעך.** אף זו בפועל הכתוב מדבר:
@70 **כי מצא בה ערות דבר.** מצוה עליו לגרשה שלא תמצא חן בעיניו:
@71 **לאיש אחר.** אין זה בן זוגו של ראשון, הוא הוציא רשעה מתוך ביתו וזה הכניסה:
@72 **ושנאה האיש האחרון.** הכתוב מבשרו שסופו לשנאותה, ואם לאו קוברתו, שנאמר או כי ימות:
@73 **אחרי אשר הטמאה.** לרבות סוטה שנסתרה:
@74 **אשה חדשה.** שהיא חדשה לו ואפלו אלמנה, פרט למחזיר גרושתו: **ולא יעבר עליו.** דבר הצבא: **לכל דבר.** שהוא צורך הצבא, לא לספק מים ומזון ולא לתקן דרכים, אבל החוזרים מעורכי המלחמה על פי כהן, כגון בנה בית ולא חנכו או ארס אשה ולא לקחה, מספיקין מים ומזון ומתקנין את הדרכים: **יהיה לביתו.** אף בשביל ביתו, אם בנה בית וחנכו ואם נטע כרם וחללו, אינו זז מביתו בשביל צרכי המלחמה: **לביתו.** זה ביתו: **יהיה.** לרבות את כרמו: **ושמח.** ישמח את אשתו. ותרגומו ויחדי ית אתתיה. והמתרגם ויחדי עם אתתיה, טועה הוא, שאין זה תרגום של ושמח אלא של ושמח:
@75 **לא יחבל.** אם בא למשכנו על חובו בבית דין, לא ימשכננו בדברים שעושים בהן אוכל נפש: **רחים.** היא התחתונה: **ורכב.** היא העליונה:
@76 **כי ימצא.** בעדים והתראה. וכן כל כי ימצא שבתורה: **והתעמר בו.** אינו חיב עד שישתמש בו:
@77 **השמר בנגע הצרעת.** שלא תתלוש סימני טמאה, ולא תקוץ את הבהרת: **ככל אשר יורו אתכם.** אם להסגיר אם להחליט אם לטהר:
@78 **זכור את אשר עשה ה' אלהיך למרים.** אם באת להזהר שלא תלקה בצרעת, אל תספר לשון הרע. זכור העשוי למרים שדברה באחיה ולקתה בנגעים:
@79 **כי תשה ברעך.** תחוב בחברך: **משאת מאומה.** חוב של כלום:
@81 **לא תשכב בעבוטו.** לא תשכב ועבוטו אצלך:
@82 **כבוא השמש.** אם כסות לילה הוא, ואם כסות יום החזירהו בבקר, וכבר כתוב בואלה המשפטים (שמות כב, כה) עד בא השמש תשיבנו לו, כל היום תשיבנו לו וכבוא השמש תקחנו: **וברכך.** ואם אינו מברכך, מכל מקום ולך תהיה צדקה:
@83 **לא תעשק שכיר.** והלא כבר כתוב, אלא לעבור על האביון בשני לאוין לא תעשוק שכר שכיר שהוא עני ואביון, ועל העשיר כבר הזהר (ויקרא יט, יג) לא תעשק את רעך: **אביון.** התאב לכל דבר: **מגרך.** זה גר צדק: **בשעריך.** זה גר תושב האוכל נבלות: **אשר בארצך.** לרבות שכר בהמה וכלים:
@84 **ואליו הוא נשא את נפשו.** אל השכר הזה הוא נושא את נפשו למות, עלה בכבש ונתלה באילן: **והיה בך חטא.** מכל מקום, אלא שממהרין להפרע על ידי הקורא:
@85 **לא יומתו אבות על בנים.** בעדות בנים. ואם תאמר בעון בנים, כבר נאמר איש בחטאו יומתו, אבל מי שאינו איש, מת בעון אביו, הקטנים מתים בעון אבותם בידי שמים:
@86 **לא תטה משפט גר יתום.** ועל העשיר כבר הזהר (דברים טז, יט) לא תטה משפט, ושנה בעני לעבור עליו בשני לאוין, לפי שנקל להטות משפט עני יותר משל עשיר, לכך הזהיר ושנה עליו: **ולא תחבל.** שלא בשעת הלואה:
@87 **וזכרת.** על מנת כן פדיתיך לשמור חקותי אפלו יש חסרון כיס בדבר:
@88 **ושכחת עמר.** ולא גדיש. מכאן אמרו עמר שיש בו סאתים ושכחו אינו שכחה: **בשדה.** לרבות שכחת קמה ששכח מקצתה מלקצור: **לא תשוב לקחתו.** מכאן אמרו, שלאחריו שכחה, שלפניו אינו שכחה, שאינו בבל תשוב: **למען יברכך.** ואף על פי שבאת לידו שלא במתכון, קל וחמר לעושה במתכון. אמור מעתה, נפלה סלע מידו ומצאה עני ונתפרנס בה הרי הוא מתברך עליה:
@89 **לא תפאר.** לא תטול תפארתו ממנו. מכאן שמניחין פאה לאילן: **אחריך.** זו שכחה:
@90 **לא תעולל.** אם מצאת בו עוללות לא תקחנה. ואיזו היא עוללות כל שאין לה לא כתף ולא נטף. יש לה אחד מהם הרי היא לבעל הבית. וראיתי בתלמוד ירושלמי איזו היא כתף, פסיגין זה על גב זה. נטף, אלו התלויות בשדרה ויורדות:
@92 **כי יהיה ריב.** סופם להיות נגשים אל המשפט. אמור מעתה אין שלום יוצא מתוך מריבה, מי גרם ללוט לפרוש מן הצדיק הוי אומר זו מריבה: **והרשיעו את הרשע.** יכול כל המתחיבין בדין לוקין, תלמוד לומר והיה אם בן הכות הרשע, פעמים לוקה ופעמים אינו לוקה. ומי הוא הלוקה, למוד מן הענין (פסוק ד) , לא תחסם שור בדישו, לאו שלא נתק לעשה:
@93 **והפילו השפט.** מלמד שאין מלקין אותו לא עומד ולא יושב אלא מטה: **לפניו כדי רשעתו.** ולאחריו כדי שתים. מכאן אמרו, מלקין אותו שתי ידות מלאחריו ושליש מלפניו: **במספר.** ואינו נקוד במספר, למד שהוא דבוק, לומר במספר ארבעים ולא ארבעים שלמים, אלא מנין שהוא סוכם ומשלים לארבעים, והן ארבעים חסר אחת:
@94 **לא יסיף.** מכאן אזהרה למכה את חברו: **ונקלה אחיך.** כל היום קוראו רשע ומשלקה קראו אחיך:
@95 **לא תחסם שור בדישו.** דבר הכתוב בהוה והוא הדין לכל בהמה חיה ועוף העושים במלאכה שהיא בדבר מאכל. אם כן למה נאמר שור, להוציא את האדם: **בדישו.** יכול יחסמנו מבחוץ, תלמוד לומר לא תחסם שור מכל מקום, ולמה נאמר דיש, לומר לך מה דיש מיוחד דבר שלא נגמרה מלאכתו וגדולו מן הארץ, אף כל כיוצא בו, יצא החולב והמגבן והמחבץ שאין גדולו מן הארץ, יצא הלש והמקטף שנגמרה מלאכתו לחלה, יצא הבודל בתמרים ובגרוגרות שנגמרה מלאכתן למעשר:
@96 **כי ישבו אחים יחדו.** שהיתה להם ישיבה אחת בעולם, פרט לאשת אחיו שלא היה בעולמו: **יחדו.** המיוחדים בנחלה, פרט לאחיו מן האם: **ובן אין לו.** עין עליו: בן או בת, או בן הבן, או בת הבן, או בן הבת, או בת הבת:
@97 **והיה הבכור.** גדול האחים הוא מיבם אותה: **אשר תלד.** פרט לאילונית שאינה יולדת: **יקום על שם אחיו.** זה שיבם את אשתו יטול נחלת המת בנכסי אביו: **ולא ימחה שמו.** פרט לאשת סריס ששמו מחוי:
@98 **השערה.** כתרגומו לתרע בית דינא:
@99 **ועמד.** בעמידה: **ואמר.** בלשון הקדש, ואף היא דבריה בלשון הקדש:
@100 **וירקה בפניו.** על גבי קרקע: **אשר לא יבנה.** מכאן למי שחלץ שלא יחזור וייבם, דלא כתיב אשר לא בנה, אלא אשר לא יבנה, כיון שלא בנה שוב לא יבנה:
@101 **ונקרא שמו** וגו' **.** מצוה על כל העומדים שם לומר חלוץ הנעל:
@102 **כי ינצו אנשים.** סופן לבא ליד מכות, כמו שנאמר מיד מכהו. אין שלום יוצא מתוך ידי מריבה:
@103 **וקצתה את כפה.** ממון דמי בשתו. הכל לפי המביש והמתביש. או אינו אלא ידה ממש, נאמר כאן לא תחוס, ונאמר להלן בעדים זוממין (לעיל יט, יג) לא תחוס, מה להלן ממון, אף כאן ממון:
@104 **אבן ואבן.** משקלות: **גדולה וקטנה.** גדולה שמכחשת את הקטנה, שלא יהא נוטל בגדולה ומחזיר בקטנה:
@105 **לא יהיה לך.** אם עשית כן, לא יהיה לך כלום:
@106 **אבן שלמה וצדק יהיה לך.** אם עשית כן יהיה לך הרבה:
@108 **זכור את אשר עשה לך.** אם שקרת במדות ובמשקלות הוי דואג מגרוי האויב, שנאמר (משלי יא, א) מאזני מרמה תועבת ה', וכתיב בתריה בא זדון ויבא קלון:
@109 **אשר קרך בדרך.** לשון מקרה. דבר אחר לשון קרי וטמאה, שהיה מטמאן במשכב זכור. דבר אחר לשון קור וחום, צננך והפשירך מרתיחתך, שהיו כל האמות יראים להלחם בכם ובא זה והתחיל והראה מקום לאחרים. משל לאמבטי רותחת שאין כל בריה יכולה לירד בתוכה, בא בן בליעל אחד קפץ וירד לתוכה. אף על פי שנכוה, הקרה אותה בפני אחרים: **ויזנב בך.** מכת זנב, חותך מילות וזורק כלפי מעלה: **כל הנחשלים אחריך.** חסרי כח מחמת חטאם, שהיה הענן פולטן: **ואתה עיף ויגע.** עיף בצמא, דכתיב (שמות יז, ג) ויצמא שם העם למים, וכתיב אחריו ויבא עמלק: **ויגע.** בדרך: **ולא ירא.** עמלק, **אלהים' מלהרע לך** :
@110 **תמחה את זכר עמלק.** מאיש ועד אשה מעולל ועד יונק משור ועד שה (שמואל א' טו, ג) . שלא יהא שם עמלק נזכר אפלו על הבהמה, לומר בהמה זו משל עמלק היתה:

@3 **ועשתה את צפרניה** . תגדלם כדי שתתנוול לשון רש"י כדברי רבי עקיבא (יבמות מח) וכן פירש אונקלוס והנה לדעתם יהיה "ועשתה" כמו ועשת את התבואה (ויקרא כה כא) כי הצמיחה תקרא עשייה אבל בספרי (תצא ז) אמר ראיה לדברי רבי אליעזר ולא עשה רגליו ולא עשה שפמו ( יט כה) והיא ראיה גדולה לכך אני אומר כי כל אלה משפטי אבלות והכל נמשך אל ובכתה את אביה ואת אמה (פסוק יג) וצוה שתגלח ראשה כדרך האבילות כענין ויגז את ראשו (איוב א כ) דאיוב וכן גזי נזרך (ירמיהו ז כט) וכן קציצת הצפרנים אבלות כגלוח הראש ואמר והסירה את שמלת שביה מעליה כלומר תלבש בגדי אבל וישבה בביתך כאלמנה ולא תצא חוץ כלל ובכתה את אביה ואת אמה ותעשה כל זה ירח ימים כי כן דרך האבלים ועל דעת רבותינו (ספרי תצא יא) שאומרים שהכל לכער את יפיה צוה שתסיר הבגדים הנאים מעליה שהגוים ארורים הם בנותיהם מתקשטות במלחמה כדי לזנות אחריהן ותגלח את ראשה שהוא נוול גדול ותקוץ הצפרנים כי מנהג הנשים לגדל אותם ולצבעם במיני הפוך והצבעונים ויקרא הכתוב הקציצה עשייה בעבור כי שער הרגלים והשפם גם הצפרנים לגדלם יקצצו אותם והנראה בעיני כי הוא לשון מקוצר הרגילו לקצר בדבר המובן וטעמו לא עשה את רגליו ואת שפמו המעשה הנעשה בהם ירמוז לגלוח שער הרגלים והשפם או לרחיצת הרגלים עצמן וכן דעת יונתן בן עוזיאל שאמר לא שטף ית רגליה ולא ספר שפמיה וכן ועשתה את צפרניה מעשה הצפרנים והמפרשים (עיין רש"י בראשית א ז) אמרו כי טעם עשיה תקון וכן וימהר לעשות אותו (שם יח ז) והטעם בפרשה הזו מפני שהיא מתגיירת בעל כרחה ואין שואלין אותה אם תחפוץ לעזוב דתה ולהתיהד כאשר נעשה בגרים אבל יאמר לה הבעל שתשמור תורת ישראל בעל כרחה ותעזוב יראתה וזה טעם ובכתה את אביה ואת אמה כי תעזוב את עמה ואת אלהיה והוא מדרשו של רבי עקיבא אין אביה אלא עבודת כוכבים כענין שנאמר (ירמיהו ב כז) אומרים לעץ אבי אתה ולאבן את ילדתני והכלל כי היא מתאבלת על עזבה את דתה ותהיה לעם אחר ויתכן שב"ד מטבילין אותה בעל כרחה כמו שעושים בעבדים ומפני שאינה מתיהדת כמשפט הרחיק אותה הכתוב כל הזמן הזה וטעם האבלות והבכי על דעת רבותינו כדי שתתנוול אולי יעבור חשקו ממנה ור"א אמר כי נתנה לה התורה זמן כמשפט הבוכים על מת לכבוד אביה ואמה שמתו במלחמה והרב אמר במורה הנבוכים (ג מא) לחמלה עליה שתמצא מנוח לנפשה כי יש לעצבים מנוח והשקט בבכייתם ואבלם ובזמן ההוא לא יכריחנה להניח דתה ולא יבעלנה ועל דעתי אין הפנאי לחמול עליה רק שיעקר שם ע"ז מפיה ומלבה ולכבות עוד גחלת הנדוד והפרוד מאביה ומאמה ומעמה שאין הגון לשכב עם אשה אנוסה ומתאבלת כמו שהזכירו רבותינו ז"ל (נדרים כ) בממזרים בני גרושת הלב וכל שכן זאת הצועקת בלבה לאלהיה להצילה ולהשיבה אל עמה ואל אלהיה והנה כאשר יודיעוה שנכריחנה לעזוב את עמה ומולדתה ותתיהד נאמר לה תתנחמי על אביך ועל אמך ועל ארץ מולדתך כי לא תוסיפי לראותם עוד עד עולם אבל תהי אשה לאדוניך כדת משה ויהודית והנה אז ניתן לה זמן שתבכה ותתאבל כמשפט המתאבלים להשקיט ממנה צערה ותשוקתה כי בכל עצב יהיה מותר וניחום אחרי כן והנה בזמן הזה לקחה עצה בנפשה על הגירות ונעקר קצת מלבה ע"ז שלה ועמה ומולדתה כי נחמה עליהם ודבקה באיש הזה שידעה כי תהיה אליו והורגלה עמו ולכך אמר הכתוב והבאתה אל תוך ביתך ודרשו (ספרי ז) ביתך ולא אל בית אחר וכן וישבה בביתך שתשב כל הזמן הזה בבית שהוא משתמש בו (שם ט) אולי תחפוץ ותתרצה בו ועל הכלל כי זה כולו בעבור ההכרח אבל אם רצתה להתגייר בחפץ נפשה בבית דין כמשפט הרי היא מותרת מיד גם לו גם לאביו ולאחיו וכך אמרו בפרק החולץ (יבמות מז) ובכתה את אביה ואת אמה ירח ימים במה דברים אמורים שלא קבלה עליה אבל קבלה עליה מטבילה ומותרת מיד ואפשר כי בכל השבויות במלחמה נעשה כתורה הזאת כי מפני היראה תאמרנה להתגייר ואמר (פסוק יד) ושלחתה לנפשה שתעשה כרצונה ולא נכריחנה לשמור דת משה ויהודית כי המתגיירת ברצון נכריח אותה לשמור התורה ואם תחלל השבת תסקל ואם תאכל החזיר תלקה כדין ישראל המשתמד וגם זאת אם הודית בפיה הגירות בלא הכרח לא נשלח אותה לנפשה שאפילו נחשב שהיתה גירותה מפני היראה דינה כישראלית גמורה שכבר העלינו (יבמות כד) הלכה כולם גרים הם
@4 **ואחר כן תבוא אליה ובעלתה** . אמרו בספרי (תצא יג) אין לך בה אלא מצות בעילה נתכוונו לומר שאין קדושי כסף ושטר תופסין בה וגם הבעילה לא לשם קדושין שדינה עדיין כעובדת כוכבים שאין קדושין תופסין בה אלא שיתיר לו הכתוב בעילתה ומפני שאמר והיתה לך לאשה יורה שהיא אשתו גמורה ואם זנתה תחתיו תדון כאשת איש וכך אמרו בגמרא במסכת קידושין (כב) ולקחת לך לאשה ליקוחין יש לך בה כלומר אחר המעשים הללו ובספרי (שם) והיתה לך לאשה כענין שנאמר שארה כסותה ועונתה לא יגרע א"כ היא אשתו לגמרי כי התורה הקנתה אותה לו ועל דרך הפשט יראה שאסור לבעול אותה עד שיעשה כל התורה הזאת וזה טעם ואחר כן תבוא אליה ובעלתה ומה שאמר וחשקת בה ולקחת לך לאשה שיקחנה להיות לו לאשה אחר המעשים האלה אשר יצוה וכן ואקח אותה לי לאשה (בראשית יב יט) אבל בגמרא במסכת קידושין (כא) אמרו שהוא מותר לבוא עליה ביאה ראשונה וזהו ולקחת לך לאשה ודרשו (שם כב) והבאתה אל תוך ביתך מלמד שלא ילחצנה במלחמה יחברו אותה למעלה ולקחת לך לאשה כשתביאנה אל תוך ביתך והנה הוא שובה אותה במלחמה ומביאה אל ביתו ואל עירו ובועל אותה לשבור את לבו הזונה ואחרי הביאה הראשונה תאסר עליו עד שיעשה לה את כל התורה הזאת וזה דרך הגמרא במקומות רבים אבל ראיתי בירושלמי במסכת סנהדרין (עי' ירושלמי מכות ב ו) רבי יוחנן שלח לרבנין דתמן תרין מילין אתון אמרין בשם רב ולית אינון כן אתם אומרים בשם רב יפת תואר לא הותרה אלא בעילה ראשונה בלבד ואני אומר לא בעילה ראשונה ולא שנייה אלא לאחר כל המעשים הללו ואחר כן תבוא אליה ובעלתה אחר כל המעשים האלו וזהו משמעותו של מקרא
@5 **ושלחתה לנפשה** . אמרו בספרי (תצא יד) ולא לבית אביה ולא ידעתי אם לומר שהיא יהודית ואין מניחין אותה לעזוב תורת ישראל ולשוב אל עמה ואל אלהיה או לומר שלא ישלחנה לבית אביה על ידי שלוחים כי יסייע ידי עוברי עבירה אבל הוא יוציאנה מביתו לגור באשר תמצא כי אולי תשאר בארץ ותלך אחרי הבחורים ותנשא לאחד מהם והנה כיון שהכתוב אומר שישלחנה לנפשה ומזהיר שלא ימכרנה בכסף ולא יתעמר בה כשפחה נלמוד שאינה צריכה ממנו גט אבל הכתוב עשה אותה אשת איש בהיותה עמו וכאשר ישנא אותה ישלחנה כאנוסה ויתכן כי טעם הכתוב לומר שאם יבעלנה ויחפוץ בה תהיה לו לאשה אבל אם יבעלנה ולא תהיה ערבה עליו ולא יחפוץ בה כענין אמנון עם תמר ( יג טו) ישלחנה לנפשה והכל תלוי בבעילה הזאת כי אם אחרי בעילתה תעמוד עמו ימים ויבא עליה אם יחזור וישנא אותה כאיש אשר ישנא את אשתו כבר נעשית אשתו והנה היא יהודית ומתגרשת בגט לא תתעמר בה כמו והתעמר בו ומכרו (להלן כד ז) ועשאו אונקלוס לשון סחורה ורבותינו בספרי (תצא טז) ובגמרא (סנהדרין פה) יעשו אותם לשון שמוש והנה הוא לשון אזהרה שלא ישתמש בה כשפחה כלל ואם נשתמש בה לוקה והנראה בעיני לפי פשוטו כי לא תתעמר הוא כמו לא תתאמר מלשון יתאמרו כל פועלי און (תהלים צד ד) וכן את ה' האמרת היום (להלן כו יז) וכן ובכבודם תתימרו (ישעיהו סא ו) בחלוף האל"ף ביו"ד וכלם רוממות וגדולה האמרת היום רוממת וגדלת אותו להיות לך לאלהים האמירך היום (להלן כו יח) רומם וגדל אותך על כל העמים להיות לו לעם סגולה וכולם נגזרו מן בראש אמיר (ישעיהו יז ו) יאמר לא תתרומם ותתגדל בה להיות אתה אדוניה למוכרה ולהשתמש בה כשפחה וכן יקראו בערבי האדון אמיר ושמוש העי"ן והאל"ף כאחד מורגל בלשון פדעהו מרדת שחת (איוב לג כד) פדאהו כמו שפירשתי (במדבר יב ד) במלת פתע וכן מעשה צעצועים (דהי"ב ג י) כמו באל"ף מן הצאצאים והצפיעות (ישעיהו כב כד) הבנים והבנות כי תרגום כרובים כרביא ובלשון חכמים עומדות אומדות בקיאין בקיעין עדין אדין עורכי הדיינין ארכי עריס אריס ושנינו (שבת עו) חלב כדי גמיעה ושאלו בגמרא (שם עז) גמיעה או גמיאה ותרצו הגמיאיני נא מעט מים (בראשית כד יז) ואעפ"כ אומרים ממנו מגמע לא יגמע ופולט אבל מגמע ובולע (שם קיא) ובמשנה במסכת כלים בתוספתא שנינו מרדא במקום מרדע ואין מקפידין כלל בחלוף שתי אותיות הללו וכן במקומות רבים ורש"י כתב לא תתעמר בה לא תשתמש בה בלשון פרסי קורין לעבודה ושמוש עמירה מיסודו של רבי משה הדרשן למדתי זאת וזה אמת שכן ראיתי בירושלמי תמן צווחין לפעלא טבא עמירא בפרק אמר רבי עקיבא (שבת פ"ט ה"א) ובפרק כל הצלמים (ע"ז פ"ג ה"ו) ומורגל הוא אף בלשון ארמי כמו שכתוב במגלת שושן ושדר מלכא דאתור על כולהון עמירה דנינוה ועל כל דעמרין על יד ימא ועל עמור דכרמלא ודגלעד ואהפיכו פתגמא דנבוכדנצר כולהון עמורייא דארעא ולא תדחלון מיניה וכן במקומות רבים בספר ההוא יקראו יושבי הארץ "עמורי ארעא" כלומר הנעבדים לארץ והמשתמשין בה או שצוה מלך אשור על אנשי המלחמה והם הנקראים "עבדי הארץ" כי הם הנעבדים למלך במלחמותיו הם אנשי מלחמתו ופרשיו כלשון עבדו את כדלעומר (בראשית יד ד) ועבדו בו גוים רבים (ירמיהו כז ז) תחת אשר עניתה אמרו בספרי (תצא טז) אפילו לאחר מעשה יחידי והוא מה שהזכרנו (בפסוק יג) שהם סבורים שמותר לבא עליה ביאה ראשונה מיד שהביאה אל תוך ביתו ומאותה שעה הוא מוזהר עליה בעמור ובמכירה
@7 **לא יוכל לבכר את בן האהובה** . אזהרה שלא יעשה זה וכן כולם לא תוכל לאכול בשעריך (לעיל יב יז) לא תוכל לתת עליך איש נכרי (לעיל יז טו) ואמר אונקלוס בכולם לית לך רשו והטעם לא תתן יכולת לנפשך לעשות ככה והוא מפליג באזהרה וכן כי את הבכר בן השנואה יכיר לתת לו פי שנים מצות עשה שינחילנו פי שנים והנה המשוה את הבכור לאחיו בנחלתו עובר בלא תעשה ועשה ואע"פ שאין דבריו קיימים בדין וכל שכן אם לא רצה להודיע שהוא הבכור וטען שהוא פשוט והנחילו כאחד מבניו מדעתו שהוא הבכור שעובר בהן ואלו מצות מחודשות וממה שאמר הכתוב "על פני בן השנואה הבכור" יראה לי שאין המצוה הזאת והדין הזה נוהג אלא בחיי הבכור אבל אם מת הבכור בחיי אביו אע"פ שהוא יורש חלק בכורתו בקבר ומורישו מן הדין לבניו אם רצה הזקן ואמר יירשו בני כך וכך בנכסי ובניו של בני הבכור יטלו כך וכך בנכסי דבריו קיימין כדרך שהם קיימים במקום שאין שם בכור וכן איננו עובר בלאו הזה אם לא הכיר הבכור לאחר מותו כי לא מצאתי "על פני" רק בחייו על פני אהרן אביהם (במדבר ג ד) על פני תרח (בראשית יא כח) וכן כולם
@9 **בן סורר ומורה** . על דעת רבותינו (סנהדרין סח) אינו קטן שהקטן פטור מכל עונשין שבתורה ומכל המצות אבל הוא המביא שתי שערות והנה יש עליו שני עונשין האחד שהוא מקלה אביו ואמו וממרה בהם והשני שהוא זולל וסובא עובר על מה שנצטוינו (ויקרא יט ב) קדושים תהיו ונאמר עוד (לעיל יג ה) ואותו תעבודו ובו תדבקון כאשר פירשתי (לעיל ו יג) שנצטווינו לדעת השם בכל דרכינו וזולל וסובא לא ידע דרך ה' ועל הכלל אין בו עתה חטא מות ועל שם סופו הוא נדון כמו שהזכירו רבותינו (סנהדרין עא) וזה טעם וכל ישראל ישמעו ויראו כי לא הומת בגודל חטאו אלא ליסר בו את הרבים ושלא יהיה תקלה לאחרים וכן דרך הכתוב שיזהיר כן כאשר ימיתו לגדר כדי שתהיה במיתתם תקנה לאחרים כי הזכיר כן בזקן ממרא (לעיל יז יג) לפי שאין בהוראתו חטא שיהיה ראוי למות בו רק הוא להסיר המחלוקת מן התורה כאשר פירשתי שם (בפסוק יא) וכן בעדים זוממין (לעיל יט כ) שנהרגין ולא הרגו וכן הזכיר במסית (לעיל יג יב) לפי שהוא נהרג בדבורו הרע בלבד אע"פ שלא עבד הניסת ע"ז ולא שמע אליו אבל מיתתו ליסר הנשארים וגם זו מצוה מחודשת או מבוארת מן כבד את אביך ואת אמך (שמות כ יב) ואיש אמו ואביו תיראו (ויקרא יט ג)
@13 **ותלית אתו** . "אמרו רבותינו (סנהדרין מא א): "כל הנסקלין - נתלין". וזה שנאמר "כי קללת אלהים תלוי" - זלזולו של מלך, שהאדם עשוי בדמות דיוקנו של מלך, וישראל בניו הם. משל לשני אחים דומים זה לזה וכו'", לשון רש"י.
@13 ו"כל הנסקלים נתלין" דברי יחיד הם, והלכה כדברי חכמים (שם) שאינו נתלה אלא המגדף והעובד עבודה זרה. וזה טעם (דברים כא כג): "כי קללת אלהים תלוי", שיאמרו, מפני מה זה תלוי? - מפני שבירך את השם או שעבד עבודה זרה פלונית בכך וכך עבודה, וכך וכך אות ומופת ראה בה. והסיפור בה ובעבודתה ייקרא קללה.
@13 או שהוא לשון זילזול, כאשר הזכיר הרב, מן (מלכים א ב ח): "והוא קללני קללה נמרצת", (שמואל א ג יג): "כי מקללים להם בניו", בוזים.
@13 והמשל בשני האחים התאומים יש לו סוד, איננו כאשר חשב הרב בישראל שנקראו בנים למקום.
@13 ועל דרך הפשט יאמר: כי יהיה באיש חטא גדול שראוי להמיתו עליו ולתלותו על עץ לגודל חטאו, אף על פי כן לא תלין נבלתו על העץ, כי הארור מכל האדם והמקולל בהם הוא התלוי, אין בכל המיתות מיתה מנוולת ובזויה כמוה, ואין ראוי שנטמא הארץ ותהיה קללת האלהים בארץ הקדושה, כי שם ציווה את הברכה חיים עד העולם.
@13 ולכן צוה יהושע (יהושע י כ): "ויורידום מעל העצים".
@13 ועל דעתי, הענין בבני שאול המוקעים (שמואל ב כא) מפני שלא היו תלויים בבית דין של ישראל ולא מיד ישראל כלל, אבל דוד נתנם לגבעונים לעשות בהם כרצונם, והם אשר הוקיעום ולא רצו לקברם, לפרסם נקמתם מהם והנשארים ישמעו וייראו. וכאשר נתך עליהם מים מן השמים, אז ידע דוד שנמחל עונם, ונעתר אלהים לארץ, כי פקד ה' את הארץ במטר ויכלה הרעב, ואז צוה וקברו אותם עם אבותם, לכבוד המלכות, לא לחיובו כלל, שלא נצטוינו אלא שלא נטמא אנחנו את הארץ במי שנתלה אותו. והנה, ה' לא רצה עוונם בתלייתם מיד, להודיע כי ה' אוהב גרים, כדברי רבותינו (יבמות עט).
@13 ורבי אברהם אמר: על דרך הפשט, כי אלהים פועל, והקללה תבוא אל מקום קרוב מהתלוי, ויש לו סוד מודבק בנפש, על כן לא תטמא את אדמתך.
@13 והנה, המלין תלוי על העץ עובר בלא תעשה ועשה. ורבותינו (סנהדרין מו) דרשו כן בכל המלין את מתו שלא לכבודו: "מה עץ שהוא נוול אף כל שהוא נוול". והנה, לדעתם "כי קללת אלהים תלוי" לומר, אע"פ שזה ראוי לנוולו לגודל חטאו לא תעשה כן, כי קללת אלהים תלוי.
@13 ועל המשל של שני אחין יהיה כל המלין בטעם הזה, וכן הקללה שהזכיר רבי אברהם ממנה יהיה בכל בית אשר יהיה שם מת, ועל כן יטמא (במדבר יט יד): "כל הבא אל האהל וכל אשר באהל".
@13 "ולא תטמא את אדמתך" - על דעת רבותינו, איננו טעם בלבד בעבור שלא תטמא את אדמתך, שאם-כן יהיה מותר בחוצה לארץ, אבל הוא לאו שני.
@13 והנה, המלין התלוי או אפילו המת בארץ עובר בשני לאוין ועשה, ובחוצה לארץ בעשה ולא תעשה אחד, שהוא למד מן התלוי כאשר פירשתי. ומן הלאו הזה קבר יהושע מלכי כנען ביומן, אף על פי שאין בתלייתן הקללה שהזכירו רבותינו במגדף ועובד עבודה זרה, אבל היה בהם משום טומאת הארץ. או שחשש לקללת אלהים מן המשל של שני האחים, כאשר פירשתי.
@15 **לא תראה את שור אחיך או את שיו נדחים** . זו מצוה מבוארת שאמר בתורה (שמות כג ד) כי תפגע שור אויבך או חמורו תועה השב תשיבנו לו והוסיף בכאן לאמר "נדחים" כי "תועה" שתעה מדרכו ויכול להטותו הדרך בלא עמל גדול ועתה הזכיר "נדחים" שברחו ממנו והרחיקו והזכיר "שה" שהוא כאבד ולכך ביאר בכאן ואם לא קרוב אחיך אליך ולא ידעתו ואספתו אל תוך ביתך ואמר וכן תעשה לחמורו שהוא בהמה טמאה וכן תעשה לשמלתו אע"פ שאין השמלה חביבה על בעליה כבעלי החיים ואין ההפסד בה מצוי כבהם שאפשר שימותו וכן תעשה לכל אבדת אחיך מכל כלי ביתו אף על פי שאינן חביבין כשמלתו אשר יכסה בה ועל מדרש רבותינו (ספרי מה ב"מ ל) הוסיף עוד בכאן דברים רבים כגון והתעלמת פעמים שאתה מתעלם השב אפילו מאה פעמים (ב"מ לא) תשיבם אפילו לגנתו ולחרבתו (שם) והחזירה בסימנים ודברים אחרים נדרשים בפרשה
@16 **ואם לא קרוב אחיך אליך** . שאינו קרוב אצלך כי אינך מתחייב ללכת אל ארץ אחרת עם האבדה להשיבה אליו או שלא ידעת אותו כלל ובספרי (תצא מז) אין לי אלא קרוב רחוק מנין תלמוד לומר ולא ידעתו וא"כ יאמר ואם לא קרוב אחיך אליך בעירך שתשאל עליו ותדענו יהיה עמך עד דרוש אחיך אותו
@20 **כי יקרא קן צפור לפניך** . גם זו מצוה מבוארת מן אותו ואת בנו לא תשחטו ביום אחד (ויקרא כב כח) כי הטעם בשניהם לבלתי היות לנו לב אכזרי ולא נרחם או שלא יתיר הכתוב לעשות השחתה לעקור המין אע"פ שהתיר השחיטה במין ההוא והנה ההורג האם והבנים ביום אחד או לוקח אותם בהיות להם דרור לעוף כאלו יכרית המין ההוא וכתב הרב במורה הנבוכים (ג מח) כי טעם שלוח הקן וטעם אותו ואת בנו לא תשחטו ביום אחד כדי להזהיר שלא ישחוט הבן בעיני האם כי יש לבהמות דאגה גדולה בזה ואין הפרש בין דאגת האדם לדאגת הבהמות על בניהם כי אהבת האם וחנותה לבני בטנה איננו נמשך אחרי השכל והדבור אבל הוא מפעולת כח המחשבה המצויה בבהמות כאשר היא מצויה באדם ואם כן אין עיקר האיסור באותו ואת בנו רק בבנו ואותו אבל הכל הרחקה ויותר נכון בעבור שלא נתאכזר ואמר הרב ואל תשיב עלי ממאמר החכמים (ברכות לג) האומר על קן צפור יגיעו רחמיך כי זו אחת משתי סברות סברת מי שיראה כי אין טעם למצות אלא חפץ הבורא ואנחנו מחזיקים בסברא השניה שיהיה בכל המצות טעם והוקשה עליו עוד מה שמצא בב"ר (מד א) וכי מה איכפת לו להקב"ה בין שוחט מן הצואר לשוחט מן העורף הא לא נתנו המצות אלא לצרף בהם את הבריות שנאמר (משלי ל ה) כל אמרת אלוה צרופה וזה הענין שגזר הרב במצות שיש להם טעם מבואר הוא מאד כי בכל אחד טעם ותועלת ותקון לאדם מלבד שכרן מאת המצוה בהן יתברך וכבר ארז"ל (סנהדרין כא) מפני מה לא נתגלו טעמי תורה וכו' ודרשו (פסחים קיט) ולמכסה עתיק זה המגלה דברים שכסה עתיק יומין ומאי ניהו טעמי תורה וכבר דרשו בפרה אדומה (במדב"ר יט ג ד) שאמר שלמה על הכל עמדתי ופרשה של פרה אדומה חקרתי ושאלתי ופשפשתי אמרתי אחכמה והיא רחוקה ממני (קהלת ז כג) ואמר ר' יוסי בר' חנינא אמר לו הקב"ה למשה לך אני מגלה טעם פרה אדומה אבל לאחרים חקה דכתיב (זכריה יד ו) והיה ביום ההוא לא יהיה אור יקרות וקפאון יקפאון כתיב דברים המכוסים מכם בעולם הזה עתידין להיות צפויים לעולם הבא כהדין סמיא דצפי דכתיב (ישעיהו מב טז) והולכתי עורים בדרך לא ידעו וכתיב (שם) אלה הדברים עשיתים ולא עזבתים שכבר עשיתים לר' עקיבא הנה בארו שאין מניעות טעמי תורה ממנו אלא עורון בשכלנו ושכבר נתגלה טעם החמורה שבהם לחכמי ישראל וכאלה רבות בדבריהם ובתורה ובמקרא דברים רבים מודיעין כן והרב הזכיר מהן אבל אלו ההגדות אשר נתקשו על הרב כפי דעתי ענין אחר להם שרצו לומר שאין התועלת במצות להקב"ה בעצמו יתעלה אבל התועלת באדם עצמו למנוע ממנו נזק או אמונה רעה או מדה מגונה או לזכור הנסים ונפלאות הבורא יתברך ולדעת את השם וזהו "לצרף בהן" שיהיו ככסף צרוף כי הצורף הכסף אין מעשהו בלא טעם אבל להוציא ממנו כל סיג וכן המצות להוציא מלבנו כל אמונה רעה ולהודיענו האמת ולזוכרו תמיד ולשון זו האגדה עצמה הוזכרה בילמדנו (תנחומא שמיני ח) בפרשת זאת החיה וכי מה איכפת לו להקב"ה בין שוחט בהמה ואוכל או נוחר ואוכל כלום אתה מועילו או כלום אתה מזיקו או מה איכפת לו בין אוכל טהורות או אוכל טמאות אם חכמת חכמת לך (משלי ט יב) הא לא נתנו המצות אלא לצרף את הבריות שנאמר (תהלים יב ז) אמרות ה' אמרות טהורות ונאמר כל אמרת אלוה צרופה למה שיהא מגין עליך הנה מפורש בכאן שלא באו לומר אלא שאין התועלת אליו יתעלה שיצטרך לאורה כמחושב מן המנורה ושיצטרך למאכל הקרבנות וריח הקטרת כנראה מפשוטיהם ואפילו הזכר לנפלאותיו שעשה שצוה לעשות לזכר ליציאת מצרים ומעשה בראשית אין התועלת לו רק שנדע אנחנו האמת ונזכה בו עד שנהיה ראויים להיות מגן עלינו כי דבורנו וזכרנו בנפלאותיו מאפס ותוהו נחשבו לו והביא ראיה מן השוחט מן הצואר והעורף לומר שכולם לנו ולא להקב"ה לפי שלא יתכן לומר בשחיטה שיהא בה תועלת וכבוד לבורא יתברך בצואר יותר מהעורף או הניחור אלא לנו הם להדריכנו בנתיבות הרחמים גם בעת השחיטה והביאו ראיה אחרת או מה איכפת לו בין אוכל טהורות והם המאכלים המותרים לאוכל טמאות והם המאכלים האסורים שאמרה בהם התורה (ויקרא יא כח) טמאים המה לכם ורמז שהוא להיותנו נקיי הנפש חכמים משכילי האמת ואמרם אם חכמת חכמת לך הזכירו כי המצות המעשיות כגון שחיטת הצואר ללמדנו המדות הטובות והמצות הגזירות הגדורות במינין לזקק את נפשותינו כמו שאמרה תורה (שם כ כה) ולא תשקצו את נפשותיכם בבהמה ובעוף ובכל אשר תרמוש האדמה אשר הבדלתי לכם לטמא א"כ כלם לתועלתנו בלבד וזה כמו שאמר אליהוא (איוב לה ו) אם חטאת מה תפעל בו ורבו פשעיך מה תעשה לו ואמר (שם פסוק ז) או מה מידך יקח וזה דבר מוסכם בכל דברי רבותינו ושאלו בירושלמי בנדרים (פ"ט ה"א) אם פותחין לאדם בכבוד המקום בדברים שבינו לבין המקום והשיבו על השאלה הזאת אי זהו כבוד המקום כגון סוכה שאיני עושה לולב שאיני נוטל תפילין שאיני מניח והיינו כבוד המקום משמע דלנפשיה הוא דמהני כהדא אם צדקת מה תתן לו או מה מידך יקח אם חטאת מה תפעל בו ורבו פשעיך מה תעשה לו הנה בארו שאפילו הלולב והסוכה והתפילין שצוה בהן שיהו לאות על ידך ולזכרון בין עיניך כי ביד חזקה הוציאך ה' ממצרים אינן לכבוד ה' יתברך אבל לרחם על נפשותינו וכבר סדרו לנו בתפלת יום הכפורים אתה הבדלת אנוש מראש ותכירהו לעמוד לפניך כי מי יאמר לך מה תעשה ואם יצדק מה יתן לך וכן אמר בתורה (לעיל י יג) לטוב לך כאשר פירשתי (שם פסוק יב) וכן ויצונו ה' לעשות את כל החקים האלה ליראה את ה' אלהינו לטוב לנו כל הימים (לעיל ו כד) והכוונה בכלם לטוב לנו ולא לו יתברך ויתעלה אבל כל מה שנצטוינו שיהיו בריותיו צרופות ומזוקקות בלא סיגי מחשבות רעות ומדות מגונות וכן מה שאמרו (ברכות לג) לפי שעושה מדותיו של הקב"ה רחמים ואינן אלא גזרות לומר שלא חס האל על קן צפור ולא הגיעו רחמיו על אותו ואת בנו שאין רחמיו מגיעין בבעלי הנפש הבהמית למנוע אותנו מלעשות בהם צרכנו שאם כן היה אוסר השחיטה אבל טעם המניעה ללמד אותנו מדת הרחמנות ושלא נתאכזר כי האכזריות תתפשט בנפש האדם כידוע בטבחים שוחטי השורים הגדולים והחמורים שהם אנשי דמים זובחי אדם אכזרים מאד ומפני זה אמרו (קידושין פב) טוב שבטבחים שותפו של עמלק והנה המצות האלה בבהמה ובעוף אינן רחמנות עליהם אלא גזירות בנו להדריכנו וללמד אותנו המדות הטובות וכן יקראו הם כל המצות שבתורה עשה ולא תעשה גזירות כמו שאמרו (מכילתא בחדש ו) במשל המלך שנכנס למדינה אמרו לו עבדיו גזור עליהם גזירות אמר להם כשיקבלו מלכותי אגזור עליהם גזירות כך אמר הקב"ה קבלתם מלכותי אנכי ה' אלהיך (שמות כ ב) קבלו גזירותי לא יהיה לך וכו' (שם פסוק ג) אבל במדרשו של רבי נחוניא בן הקנה בשלוח הקן מדרש שיש במצוה סוד אמר רבי רחמאי מאי דכתיב שלח תשלח את האם ולא אמר את האב אלא שלח תשלח את האם בכבוד אותה בינה שנקראת אם העולם דכתיב (משלי ב ג) כי אם לבינה תקרא מאי ואת הבנים תקח לך אמר רבי רחמאי אותם בנים שגדלה ומאי ניהו שבעת ימי הסוכה ודיני שבעת ימי השבוע וכו' והנה המצוה הזאת רומזת לענין גדול ולכך שכרה מרובה למען ייטב לך והארכת ימים
@22 **ועשית מעקה** . מצות המעקה מחודשת או מבוארת מלא תעמוד על דם רעך (ויקרא יט טז) אבל מצות הכלאים מבוארת שכבר אמר (שם פסוק יט) שדך לא תזרע כלאים והנה במשמע ההוא כל מקום הנזרע והוסיף בכאן כי אם יזרע הכרם כלאים יקדש הזרע אשר יזרע ותבואת הכרם לומר שיאסר בהנאה כהקדש וטעם "פן" כמו כי תקדש וכן ומפתח אהל מועד לא תצאו פן תמותו (שם י ז) וכן ולא תגעו בו פן תמותון (בראשית ג ג) ויתכן שפירושו כמו פן ינכרו צרימו פן יאמרו ידינו רמה (להלן לב כז) כענין שמא לומר לא תזרע אותו כלאים פן יצמח ויאסר עליך הכל כי אינן נאסרין אלא כמו ששנינו (כלאים פ"ז ה"ז) תבואה מתקדשת משתשריש וענבים משיעשו כפול הלבן
@24 **ואמר לא תחרש בשור ובחמר** . והוא הדין לכל מיני הכלאים והיא מצוה מבוארת מן בהמתך לא תרביע כלאים (ויקרא יט יט) שדרך כל עובד אדמתו להביא צמדו ברפת אחת וירכיב אותן וביאר בשעטנז שאיננו רק בצמר ופשתים והזכיר לא תלבש ללמד שאין העליה אסורה אלא בענין לבישה
@27 **כי יקח איש אשה ובא אליה ושנאה** . טעמו: כאשר יקח האיש אשה בלקוחי התורה, שהם הקדושין בכסף, והיא המאורסה אשר יזכיר (פסוק כג);
@27 ואחרי ימים בא אליה ושנאה, שלא היתה עריבה אליו בביאתה;
@27 והשכים בבקר ובא לבית-דין וטען שלא מצאה בתולה; והנה זה מתכוין להוציאה בלא מוהר הבתולות, שהיא הכתובה שכתב לה, ומפני כי בחזקת בתולה נתקדשה אליו הוא טוען עליה שזנתה תחתיו;
@27 ולפיכך אמר הכתוב (דברים כב כ): "ואם אמת היה הדבר" כדברי הבעל, "וסקלוה"; והאמת לא יודע רק על פי שנים עדים.
@27 ולפי שהכתוב יפרש בזנוני הבתולות, כי כאשר תהיה מאורסה תסקל וכאשר לא אורסה היא פטורה, לא הוצרך לפרש כאן "ואם אמת היה שזינתה בארוסיה ושזינתה ברצונה וסקלוה", ואמר ברמז (דברים כב יא): "כי עשתה נבלה בישראל לזנות בית אביה", והנבלה היא בעשותה כן לרצונה.
@27 ו"לזנות" הוא כאשר תשטה אשה תחת אישה, כי הנערה אשר לא אורשה לא תקרא "זונה" בשכבה עם אחד העם, אבל היא מיועדת לו (שמות כב טו).
@31 **ופרשו השמלה** . הרי זה משל מחוורין הדברים כשמלה לשון רש"י והוא מדרשו של רבי ישמעאל בספרי (תצא רלז) ובמכילתא (משפטים יג) ואין צורך כי זאת לפנים בישראל מכניסין החתן והכלה לחופה ובודקין אותן והעדים משמרים להם מבחוץ והם שהחכמים קורין להם שושבינין וכאשר יפרדו נכנסין העדים שם ולוקחין השמלה אשר שכב אותה עליה ויראו הדמים וזה ידוע בתלמוד (כתובות מו ירושלמי שם פ"א ה"א) ובספרי אגדה וקורין השמלה ההיא סודר ולכך יאמר הכתוב שיפרשו אביה ואמה השמלה אשר לקחו מיד העדים ויאמרו אלה בתולי בתי ובודאי שצריך לחוור הדברים בענינים הרבה שהכתוב יקצר בהם אבל לא אמר הרי זה משל אלא המחייב מוציא שם רע אע"פ שלא בעל ופשוטו של מקרא כדברי האומר עד שבעל וכך אמרו בגמרא (שם מו) רבי אלעזר בן יעקב אומר שמלה ממש והלכה כדבריו וכן טעם הפרשה כי אמר הכתוב תחלה ולקח אבי הנערה ואמה והוציאו את בתולי הנערה ידבר בשניהם ואחר כן שב לאב לבדו ואמר אבי הנערה וגו' וחזר ואמר ופרשו השמלה בשניהם והטעם כי התביעה הזאת לאב לבדו הוא שהקנס שלו אבל שתף האם במעשה מפני שענין השמלה הנשים יתעסקו בה והן היודעות והבקיאות בדמים ולאם ראוי שתתפוש ותביא אותה לב"ד אבל טענת "את בתי נתתי לאיש הזה" לאב בלבד היא והאם לאו בעלת דברים דידיה היא או אחר שיסדר האב טענותיו בב"ד יתפוש בשמלה אשר הביאה אשתו תחת כנפות כסותה ויפרשו אותה שניהם בב"ד והנה לא הוזכרה האם בפרשה ולא באה לב"ד כלל אלא מפני ענין השמלה שהוא ממש כאשר פירשתי
@33 **וטעם וענשו אתו מאה כסף** . אחרי המלקות הנדרש מ"ויסרו אותו" (כתובות מו) כי המנהג לכתוב לבתולה מוהר חמשים כסף והנה זה הוציא עליה שם רע בעבור ששנאה ורצה להוציאה בלא כלום ולכן ענשו הכתוב במאה כסף כי התורה תעניש בכפל כענין שנים ישלם (שמות כב ג) אע"פ שהכתובה מדבריהם למי שיתנה עמה או ישאנה סתם אבל המנהג היה לכתוב מוהר לבתולות כמו שנאמר (שם שם טז) כמהר הבתולות והרוב יעשו כן ואם לא היתה כתובה לאשה הזאת למה ישים עליה עלילות דברים מפני שבא עליה ושנאה יכתוב לה גט ויפטר ממנה דכתיב (מלאכי ב טז) כי שנא שלח
@36 **ומתו גם שניהם** . להוציא לעושה מעשה חדודים שאין האשה נהנית מהם גם לרבות הבאים אחריהם לשון רבינו שלמה ולא הבינותי מהו וכי בתולה היא זו שנמעט או נצטרך לרבות הבאים אחריהם מה לי ראשון מה לי שני ושלישי ועוד היה לו לומר הבאים אחריו ובנוסחאות שלנו בספרי (תצא קב) שניהם ולא העושה מעשה חדודין כשהוא אומר גם שניהם לרבות הבאים מאחוריהם והיא ביאה שלא כדרכה וריבה אותה הכתוב בכאן וכל העריות למדות זו מזו ועל דרך הפשט גם שניהם האיש הפושע בחטא יותר שהוא התובע והמפתה והעושה מעשה וגם האשה והזכיר זה הכתוב ופירש גם שניהם האיש השוכב וגם האשה וכן דרך הכתובים לתלות החטא באיש כאשר פירשתי (ויקרא כ יז) בערות אחיו גלה ערירים יהיו ויש אומרים כי טעם האיש השוכב עם האשה והאשה תוספת ביאור כמו יביאה את תרומת ה' (שמות לה ה) אותו את נבוכדנצר (ירמיהו כז ח) ובספרי (שם) האיש השוכב עם האשה אע"פ שהיא קטנה והאשה אע"פ שנבעלה לקטן אם כן טעמו גם שניהם גם כל אחד מהם האיש או האשה המגיע מהם לחיוב
@37 **על דבר אשר ענה את אשת רעהו** . ולא יקרא ענוי רק השוכב באונס וזו כבר חייב אותה כמזנה לרצון אבל ענין הכתוב כי כאשר נראה שהאיש אוחז בה ושוכב עמה נדון האשה כמתרצה בעבור שהיתה יכולה להושע ממנו ונחשב האיש כמענה אותה כי לא פתה ולא דבר על לבה להשמע אליו ולא ידעתי בדין הצעקה אם ראינו נערה שהחזיק בה האיש והיא נלחמת בו בכל כחה ובוכה ואוחזת בבגדיו או בשערותיו להמלט ממנו ולא ידעה לצעוק למה תסקל אלא גם הצעקה בהווה לדון בה מן הסתם בעיר מפותה ובשדה אנוסה
@46 **ממזר** . שם לאיש מוזר מאחיו ויודעיו שלא יודע מאין בא כלשון וישב ממזר באשדוד והכרתי גאון פלשתים (זכריה ט ו) יאמר שלא ישב באשדוד זולתי איש נכרי וזר שיעבור בו כי יכרית גאון פלשתים ממנו והנה הנולד לאיש מאשת אביו הוא ירחיק אותו ולא יודה בו לבשתו ולכלמתו מן המעשה הרע שעשה וגם אמו תשליכנו בלילה כענין האסופי הנזכר בתלמוד (קידושין סט) והנה הוא ממזר בעיר מולדתו וכן כל העריות כדברי רבותינו בקדושין ירושלמי (פ"ג הי"ד) אמר ר' אבהו מהו ממזר מום זר
@48 **על דבר אשר לא קדמו אתכם בלחם ובמים** . מצינו (לעיל ב כח כט) אכל בכסף תשבירני ואכלתי ומים בכסף תתן לי ושתיתי כאשר עשו לי בני עשו היושבים בשעיר והמואבים היושבים בער ורבים אמרו שהם לא קדמו אותם אבל ישראל קנו מהם וזה הבל כי די למחנה שימכרו להם כאשר ירצו לקנות ועוד כי ישראל לא באו בגבול מואב והמואבים הוציאו להם לחם ומים בכסף והכתוב יספר שעשו המואבים כאשר עשו בני עשו ולמה ירחיק המואבי לעולם בעבור זה ולא יתעב האדומי ור"א אמר (לעיל ב כט) כי טעם כאשר עשו לי בני עשו והמואבים על אעברה בארצך בדרך (שם פסוק כז) אבל לא מכרו להם לחם ומים כי הם עברו בהר שעיר ובער רק מלך אדום לא הניחם לעבור דרך מדינתו אשר הוא יושב בה והוא מה שאמר (במדבר כ יח) לא תעבר בי גם זה הבל כי הם אמרו אל מלך אדום אעברה בארצך וימאן אדום נתן את ישראל עבור בגבולו (שם פסוק כא) הנה לא נכנסו כלל בגבול אדום וכן כתוב (שם כא ד) ויסעו מהר ההר דרך ים סוף לסבב את ארץ אדום כי הוצרכו לשוב לאחור דרך ים סוף מהר ההר שהוא על גבול ארץ אדום ולא באו בארץ אדום עצמה כלל ויפתח אמר בביאור (שופטים יא טז-יח) כי בעלותם ממצרים וילך ישראל במדבר עד ים סוף ויבא קדשה וישלח ישראל מלאכים אל מלך אדום לאמר אעברה נא בארצך ולא שמע מלך אדום וגם אל מלך מואב שלח ולא אבה וישב ישראל בקדש וילך במדבר ויסב את ארץ אדום ואת ארץ מואב וגו' ויחנון בעבר ארנון ולא באו בגבול מואב הנה זה מפורש שלא באו כלל בארץ אדום ולא בארץ מואב ואלו באו שם היו מוכרין להם לחם ומים כי אין המנהג לנותן רשות לעם הצבא לעבור בארצו שלא ימכר להם לחם ומים והנראה אלי כי הכתוב הרחיק שני האחים האלה שהיו גמולי חסד מאברהם שהציל אביהם ואמם מן החרב והשבי (בראשית יד טז) ובזכותו שלחם השם מתוך ההפכה (שם יט כט) והיו חייבין לעשות טובה עם ישראל והם עשו עמהם רעה האחד שכר עליו בלעם בן בעור והם המואבים והאחד לא קדם אותו בלחם ובמים כאשר קרבו למולו כמו שכתוב (לעיל ב יח יט) אתה עובר היום את גבול מואב את ער וקרבת מול בני עמון והנה הכתוב הזהירם (שם פסוק יט) אל תצורם ואל תתגר בם והם לא קדמו אותם כלל כי היה הכתוב אומר "כאשר עשו לי בני עשו המואבים והעמונים" אבל לא הזכיר עמון שלא קדמו אותם והנה עמון הרשיע בזה יותר מכולם כי בני עשו והמואבים כאשר ידעו שהוזהרו ישראל שלא יתגרו בהם הוציאו לחם ומים חוץ לגבולם ועמון לא אבה לעשות כן וזה טעם "אשר לא קדמו" שלא יצאו לקראתם בלחם ובמים כאשר עשו האחרים ולכך הקדים הכתוב "עמוני" והקדים להזכיר פשעו על דבר אשר לא קדמו אתכם ואחרי כן הזכיר "מואבי" וחטאתו ורבותינו דרשו (יבמות עו) עמוני ולא עמונית מואבי ולא מואבית מפני שהאיש דרכו לקדם ואין האשה דרכה לקדם שתוציא מזון חוץ לגבול הארץ וכן הזכירו בירושלמי (שם פ"ח ה"ג) ובמגילת רות רבתי (ד ח) מפני שדרך האיש לשכור ואין דרך האשה לשכור
@50 **לא תדרש שלמם** . מכלל שנאמר (להלן פסוק יז) עמך ישב בקרבך יכול אף זה כן ת"ל לא תדרוש שלומם לשון רש"י והמדרש הזה בספרי (תצא רנא) מטובתם מכלל שנאמר שם בטוב לו לא תוננו הוציא את אלו מאותה טובה אבל לא תדרוש שלומם נדרש בספרי לפי שנאמר (לעיל כ י) כי תקרב אל עיר וקראת אליה לשלום יכול אף עמון ומואב כן ת"ל לא תדרוש שלומם וכן בתנחומא והנראה אלי כי מלחמת עמון ומואב אסרה הכתוב עלינו לדורות והכתוב שאמר (לעיל ב ט יט) "אל תתגר בם" אינה מצוה לשעה בלבד אבל היא מצות לא תעשה לדורות זהו שאמר (שם) כי לבני לוט נתתיה ירושה והנה ארצם להם לעולם כי היא נחלה שהנחילם השם אם כן הכתוב שאמר "לא תדרוש" יצוה אם נלחם עליהם בעיר שכבשו הם מן העמים שלא נקרא להם לשלום וכן אם יבואו הם להלחם בארצנו מותר לנו לרדוף אחריהם ולכבוש מהם המדינות להכות יושבי הערים שעשו עמנו הרעה כמו שעשה יפתח (שופטים יא לג) ויכם מערוער ועד בואך מנית עשרים עיר וכן עשה דוד לכל ערי בני עמון ( יב לא) בעבור שהם פרצו הגדר תחלה ונלחמו בו ואז לא נצטרך לקרא בשלומם ונכה בנלחמים בנו כל עיר מתים הנשים והטף אם נרצה ואמרו במדרש רבה (במדב"ר כא ו) והכיתם כל עיר מבצר וכל עיר מבחור וכל עץ טוב תפילו וכל מעיני מים תסתומו (מלכים ב ג יט) אמרו לו הכתוב אומר (לעיל כ יט) לא תשחית את עצה ואתה אומר כן אמר להם על כל האומות צוה וזו קלה ובזויה היא שנאמר (מלכים ב ג יח) ונקל זאת בעיני ה' ונתן את מואב בידכם שנאמר לא תדרוש שלומם וטובתם אלו אילנות טובים וכל זה להזיקם ולצערם אבל הארץ תשאר למשפחה ההיא שהיא נחלה שהנחילם השם וזה הענין מוזכר באגדות בבראשית רבה (עד יג) ובמדרש תילים (ס א) ועל דרך הפשט טעם לא תדרוש שלומם וטובתם כאומר אע"פ שהם בני משפחתכם ואברהם אביכם אהב את אביהם כאח לו יונק שדי אמו לא תהיו אתם לו כאחים דורשי שלום וטובה כי הם הפרו ברית אחוה ותהיה מופרת לעולם והנה השם שמר לבני לוט זכות אביהם שליוה את נביאו בדרך אשר שלחו ה' ולכך הנחילם מנחלת אברהם והעניש את בניו בחטאם שלא ידבקו בישראל וכן המצרים הרחיקם שלשה דורות מפני רשעם אשר עשו עמנו רעות רבות וצרות אבל לא יתעב אותם לעולם בעבור שהיינו גרים בארצם ונמלטנו עמהם בימי הרעב בכבוד שעשו לאבינו והמליכו עליהם ממנו קצין ומושל וכן עשה עם אדום שמר להם זכות אבות שהיו מזרע קדש והרחיקם שלשה דורות בעבור שיצאו לקראתינו בחרב ולא זכרו ברית אחים והקבלה מן רבותינו (יבמות עח) כי אין דור שלישי מימי משה אבל כאשר יתגייר אחד מהם יבא הדור השלישי שלו בקהל ה'
@53 **ונשמרת מכל דבר רע** . שהשטן מקטרג בשעת הסכנה לשון רש"י והנכון בעיני בענין המצוה הזאת כי הכתוב יזהיר בעת אשר החטא מצוי בו והידוע במנהגי המחנות היוצאות למלחמה כי יאכלו כל תועבה יגזלו ויחמסו ולא יתבוששו אפילו בניאוף וכל נבלה הישר בבני אדם בטבעו יתלבש אכזריות וחמה כצאת מחנה על אויב ועל כן הזהיר בו הכתוב ונשמרת מכל דבר רע ועל דרך הפשט היא אזהרה מכל הנאסר ובספרי (תצא קיט) ונשמרת מכל דבר רע שומע אני בטומאות ובטהרות ובמעשרות הכתוב מדבר ת"ל ערוה אין לי אלא ערוה מנין לרבות עבודת גלולים וגלוי עריות ושפיכות דמים וקללת השם ת"ל ונשמרת מכל דבר רע או יכול בטומאות ובטהרות ובמעשרות הכתוב מדבר ת"ל ערוה מה ערוה מיוחדת מעשה שגלו עליו כנענים ומסלק את השכינה אף כל מעשה שגלו עליו כנענים ומסלק את השכינה כשהוא אומר "דבר" אף על לשון הרע וגם זה מן הטעם שפירשנו כי מלבד האזהרות שבאו באלה העבירות החמורות יוסיף לאו במחנה שנשמר בו מכל אלו העבירות שלא תסתלק השכינה מישראל אשר שם כאשר אמר כי ה' אלהיך מתהלך בקרב מחנך והנה העושה העבירות הגדולות במחנה כאותם שכתוב בהם (ירמיהו ז ל) שמו שקוציהם בבית אשר נקרא שמי עליו לטמאו ועוד שלא יגברו עלינו האויבים אם נעשה כמעשים הגורמים להם שיגלו מפנינו וזהו ולתת אויביך לפניך (שם) והוסיפו בו לשון הרע כדי שלא ירבו ביניהם מחלוקת ויכו ביניהם מכה רבה מאד יותר מן האויבים
@59 **וטעם לא תסגיר עבד אל אדניו** . דבק למעלה שאם יברח העבד מאדוניו אשר יצאת עליו מחנה וינצל אל מחנך לא תסגירנו לו בממון אשר יתן לך ולפי שאמר במקום אשר יבחר נראה שהוא מצוה שיהיה בן חורין ולא נעבוד בו אנחנו והטעם במצוה הזו כי עמנו יעבוד את השם ואיננו הגון שנחזירנו אל אדוניו לעבוד ע"ז ועוד שיתכן שילמד דרך מבוא העיר כי בענין כזה ילכדו מדינות רבות על ידי העבדים והשבויים הבורחים משם ורבותינו אמרו (גיטין מה) אפילו בעבד כנעני של ישראל שברח מחוצה לארץ לארץ שגם זה יעמוד לפני יושבי ארץ השם וינצל מעבוד היושבים על אדמה טמאה ושאין כל המצות נוהגות שם
@61 **לא תהיה קדשה מבנות ישראל** . מקודשת ומזומנת לזנות ולא יהיה קדש מבני ישראל מזומן למשכב לשון רש"י והנה אם הלאו הזה אזהרה באשה הנשכבת ויזהיר בהיותה מקודשת ומזומנת לזנות אם כן אין הפנויה הנבעלת במקרה ובהצנע מחייבי הלאוין וכן הקדש למה יזכיר בהיותו קדש ומזומן ואפילו הנבעל בחדרי חדרים יש בו כרת ומיתת ב"ד ועוד שהיה ראוי שיאמר לא תהיה בכם קדשה ולא יהיה בכם קדש כי "מבנות ישראל" ו"מבני ישראל" כאלו בעם אחר ידבר והנראה בעיני בלאו הזה כי הוא אזהרה לב"ד שלא יניחו אחת מבנות ישראל להיות יושבת בפרשת דרכים בעינים על הדרך לזמה או שתתקן לה קובה של זונות כמנהג ארצות זרים יושבות על הפתח בתופים ובכנורות כענין שכתוב (ישעיהו כג טז) קחי כנור סובי עיר זונה נשכחה הטיבי נגן הרבי שיר למען תזכרי וכן יזהיר לב"ד על הקדש ועל דרך הפשט אפילו שישכב עם הנשים בקובה אשר יעשה לו מזומנת לזמה או שישב בעינים על הדרך הזהירם לבית דין ויראה לי שכן דעת אונקלוס אבל צירף לזה העבד והשפחה הבאים בישראל דרך נשואין מפני שהכל יודעין בעבד הזה שנשא בת ישראל שאין לו בה קדושין והיא עמו כאשה עם בעלה אם כן היא קדשה לעיני השמש וראיתי בספרי (תצא קכו) לא תהיה קדשה מבנות ישראל אין אתה מוזהר עליה באומות ולא יהיה קדש אין אתה מוזהר עליו באומות שהיה בדין ומה אם קדשה קלה אתה מוזהר עליה בישראל קדש חמור אינו דין שתהא מוזהר עליו בישראל או חלוף אם קדש חמור אי אתה מוזהר עליו באומות קדשה קלה אינו דין שלא תהא מוזהר עליה באומות וכו' ונראה מזה שאין מדרשם כדברי אונקלוס שהרי לדבריו אין חומר בקדש יותר מן הקדשה ועוד מהו זה שאומרים אין אתה מוזהר עליו באומות וכן אם היה מדרשם בקדש לזכר הנשכב כמדרשו של רבי ישמעאל במסכת סנהדרין (נד) גם בזה לא יתכן שיאמרו אי אתה מוזהר עליו באומות שהנשכב מן הגוי בסקילה הוא אבל נראה שדעת בעל הברייתא הזו כענין שהזכרנו יזהיר לב"ד שלא תעמוד האשה על אם הדרך לזנות כי שם תנאפנה מאיסורי הביאות קרובים ורחוקים ולכן מכסות פניהן לזנות גם מאחיהם וקרוביהם והוא מה שאמר (בראשית לח טו) ויחשבה לזונה כי כסתה פניה וכן יזהיר לב"ד על המזומן להיות נשכב מן הזכרים כענין שכתוב (מלכים א יד כד) וגם קדש היה בארץ עשו ככל התועבות הגוים ומלבד האזהרה בעושי העבירה יזהיר כאן בבית דין שלא יניחו להיות קדש בעינים על הדרך כידוע מהם בארץ מצרים שעומדים על הדרך מכוסי הפנים כנשים לעשות התועבה הזאת ודרשו בברייתא הזו שאין אנו מוזהרים באחרים זולתנו אם יעשו עם רעיהם כן שלא הוזהרנו אנחנו בגוים אלא בענין ע"ז בלבד ולשון קדש וקדשה על דעת המפרשים לשון הזמנה כי מצאו אני צויתי למקודשי (ישעיהו יג ג) וכן הקדיש קרואיו (צפניה א ז) קדשו עליה מלחמה (ירמיהו ו ד) ולפי דעתי כולם מלשון קדושה כי הפורש מן הזנות נקרא קדוש כמו שנאמר (ויקרא כא ז) אשה זונה וחללה לא יקחו ואשה גרושה מאישה לא יקחו כי קדוש הוא לאלהיו והנה הנשמרת מן הערוה והזמה קדושה והנפרדת מן הקדושה ונטמאת בזמה נקראה קדשה קרוב למה שנוהג הלשון לומר ובכל תבואתי תשרש (איוב לא יב) ודשנו את המזבח (במדבר ד יג) כי הזונה המפורסמת טמאת השם רבת המהומה נפרדת מכל קדושה ואין שם זה בה רק בהיותה מזומנת לתועבה הזאת שאין לה שעת הכושר וקדושה כלל ולשון "הקדיש קרואיו" מליצה כי העושה משתה מקדש קרואיו ומטהר אותם שלא יטמאו השולחן והלחם כענין שאמר (שמואל א כ כו) בלתי טהור הוא כי לא טהור וכן (ירמיהו ו ד) קדשו עליה מלחמה שיטהרו אותם כמטהר קרואיו שלא יבדלו החברים מהם
@62 **לא תביא אתנן זונה** . הזונות יעשו באתנן שלהם מצות חושבות לכפר על חטאתן כמו שיזכירו רבותינו (ויק"ר ג א) במשל שלהן גייפא בתפוחייא ומפלגא לבאישייא ולכך אסרה תורה אתנן לכל נדר כי עתה יוסיפו לחטוא בהן וכן ענין מחיר כלב בעבור כי הצדים בכלבים ושומרי החומות יגדלו כלבים עזי נפש מזיקים את הרבים וידירו במחיריהם להיות כופר לנפשם וכן המנהג עד היום בפרשים אנשי הציד שיעמידו צורת כלביהם בשעוה לפני ע"ז שיצליחו בהם והמפרשים אמרו מפני שהוא דרך בזיון.
@62 ואמר (דברים כג יט): "גם שניהם" - לרבות שנוייהם, כגון חטין ועשאן סולת, לשון רש"י. אבל בגמרא (בבא קמא סה ב) אמרו, שבית שמאי אוסרין ובית הלל מתירין, אלא הם ולא ולדותיהם הם ולא שנוייהם.
@62 וטעם "גם שניהם", בעבור שהאחד באמת תועבה גדולה והוא האתנן כי בו נעשתה תועבת הזמה, אמר שגם שניהם יתעב ה';
@62 וכמוהו (משלי יז טו): "מצדיק רשע ומרשיע צדיק תועבת ה' גם שניהם", יתלה הקטן בגדול.
@62 וכן (דברים כב כב): "ומתו גם שניהם", כמו שפירשתי.
@62 או טעמו, שהזהיר כבר על פסולי הקרבן במומין ואמר בהם (דברים יז א): "לא תזבח לה' אלהיך שור ושה אשר יהיה בו מום כל דבר רע כי תועבת ה' אלהיך הוא", הוסיף בכאן לומר כי גם האתנן והמחיר, שגופם תמים, גם הם תועבת ה' אלהיך כמותם, והוא הנכון.
@62 וכן (משלי כ יב): "אוזן שומעת ועין רואה ה' עשה גם שניהם", ירמוז לאדם בכללו, יאמר שה' יצר את האדם ועשה גם אלו בו.
@62 וכן (משלי כ י): "אבן ואבן איפה ואיפה תועבת ה' גם שניהם", ירמוז לגוזל וחומס וכל עושק, שהם תועבות גדולות מאלו ולא יזכירם.
@63 **לא תשיך לאחיך** . גם זו מצוה מבוארת (ויקרא כה לו לז) יוסיף בכאן אזהרה גם ללוה מה שאין כן בכל דיני ממונות שאם רצה הוא לזוק בנכסיו רשאי אבל מפני רגילות החטא הזה יזהיר בו גם הלוה וביאר בכאן שיהיה רבית הנכרי מותר ולא הזכיר כן בגזל ובגנבה כמו שאמרו (ב"ק קיג) גזל גוי אסור אבל הרבית שהוא נעשה לדעת שניהם וברצונם לא נאסר אלא מצד האחוה והחסד כמו שצוה (ויקרא יט יח) ואהבת לרעך כמוך וכמו שאמר (לעיל טו ט) השמר לך פן יהיה דבר עם לבבך בליעל וגו' ועל כן אמר למען יברכך ה' אלהיך כי חסד ורחמים יעשה עם אחיו כאשר ילונו בלא רבית ותחשב לו לצדקה וכן השמיטה חסד באחים לכך אמר (שם פסוק ג) את הנכרי תגוש וקבע לו ברכה כי הכתוב לא יזכיר הברכה רק בצדקה ובחסדים לא בגזל ובגנבה ובאונאה והזכיר נשך כסף נשך אכל לבאר שהלוה סאה חטין בסאה וחצי יהיה נשך גמור אפילו לא יהיה שוה סאה וחצי בעת הפרעון כדמי סאה שהלוהו וביאר עוד כל דבר אשר ישך אפילו באבני הבנין ושאר הנלוים אולי יעלה על הדעת שאין הנשך רק בכסף שכל הדברים נקנין בו ובאוכל שהוא חיי האדם אבל בשאר הדברים נלך אחר שום הכסף לעת ההלואה והפרעון ורבותינו (ספרי קכט) עשו "לנכרי תשיך" לאו הבא מכלל עשה באחיך מפני שהוא מיותר שכבר אמר לא תשיך לאחיך
@66 **וכי תחדל לנדר לא יהיה בך חטא** . בעבור שהמקריבים עולה וזבחים לאלהים יש להם שכר טוב כענין שכתוב (תהלים סו טו) עולות מחים אעלה לך עם קטרת אילים אעשה בקר עם עתודים סלה אבוא ביתך בעולות (שם פסוק יג) ואף בקרבנות הבאים בנדבה כתוב (ויקרא א ד) ונרצה לו לכפר עליו ואומר ריח ניחוח לה' ואם כן הרי הנדרים זרוז במצוה וכתוב (תהלים קטז יח) נדרי לה' אשלם נגדה נא לכל עמו לפיכך יאמר הכתוב השמר בנדריך כי אע"פ שהם זרוז בקרבנות השם אשר הם לך לרצון אם תדור תבא לידי חטא אם לא תשלם או שתאחר לשלמו ואם לא תדור לא תמצא חטא בענין כלל כי אפילו לא תקריב קרבן כל ימיך לא יהיה בך חטא אם כן תשמור מוצא שפתיך כאשר תוציא הדבר מפיך ועשית אחרי כן כאשר דברת להשלים כל אשר נדבה רוחך להוציא מפיך ועל הדרך הזה אמר שלמה (קהלת ה ג ד) כאשר תדר נדר לאלהים אל תאחר לשלמו כי אין חפץ בכסילים וגו' טוב אשר לא תדור משתדור ולא תשלם יאמר שאין חפץ בכסילים החושבים לעשות מצוה כאשר ידרו נדרים רבים להיות להם זרוז למצוה שחשבו לעשות ולא יחשבו בלבם ולא דעת ולא תבונה לאמר אולי לא תמצא ידי להשלים כל אלה אבל יחשוב כי הרצון אשר היה לו בעת נדרו יחשב לו לטובה ולפיכך יזהיר עוד (שם שם ה) אל תתן את פיך לחטיא את בשרך ואל תאמר לפני המלאך כי שגגה היא כלומר שלא תרבה בנדרים וכאשר לא תקריבם תאמר לפני המלאך האכזרי אשר ישולח בך כי שגגה היא שהייתי סבור להקריבם ובלב שלם נדרת אותם עתה לא מצאה ידך לעשות כן כי האלהים יקצוף על קול נדריך וחבל המלאך הנזכר את מעשה ידיך
@73 **אחרי אשר הטמאה** . לרבות סוטה הנסתרת לשון רש"י ופירושו אשה שזנתה תחת בעלה אבל הסוטה הנסתרת בלבד לא נודע שהיא טמאה ואינו עובר עליה בלאו הזה וכך מפורש בפרק ראשון של יבמות (יא) מאי ונסתרה נבעלה ואמאי קרי ליה נסתרה לישנא מעליא נקט ושאלו נבעלה בהדיא כתיב בה טומאה (במדבר ה יג) ונסתרה והיא נטמאה למיקם עלה בלאו ואם כן יאמר הכתוב לא יוכל בעלה הראשון אשר שלחה לשוב לקחתה ואחרי אשר הטמאה והנה הם שני לאוין יזהיר במחזיר גרושתו משנשאת ויזהיר במחזיר אשתו שנטמאה בזנות ועל דרך הפשט אחרי אשר הוטמאה לבעל הראשון ירמוז כי כאשר ידעה איש אחר תחשב לו טמאה ואלו מצות מחודשות בגט ובחזירה וטעם הלאו הזה כדי שלא יחליפו נשותיהן זה לזה יכתוב לה גט בערב ובבוקר היא שבה אליו וזה טעם ולא תחטיא את הארץ כי זה סבה לחטאים גדולים ובספרי (תצא קלו) ולא תחטיא את הארץ להזהיר ב"ד על כך
@74 **ולא יעבר עליו לכל דבר** . דבר הצבא לכל דבר שהוא צורך הצבא לא לספק מים ומזון ולא לתקן דרכים אבל החוזרים מעורכי המלחמה על פי כהן כגון בנה בית חדש ולא חנכו ארש אשה ולא לקחה מספיקין מים ומזון ומתקנין את הדרכים לשון רש"י מדברי רבותינו (ספרי קלז סוטה מד) ואם כן יהיה "עליו" על הצבא הנזכר יאמר שלא יעבור האיש הזה על הצבא לכל דבר לא להיות פקיד על אנשי הצבא או מצביא את עם הארץ או לכל הצריך להם כגון סיפוק מים לא ישגיח עליהם רק בשמחתו והוא פירוש נכון
@77 **השמר בנגע הצרעת** . גם זו מצוה מבוארת יוסיף לאו בקוצץ בהרתו או גם בנמנע מהראות נגעו לכהן ובדין הנגעים עצמם לא הזכיר כאן אלא הזהיר בכאן רק ככל אשר יורו אתכם הכהנים הלוים כאשר צויתים לפי שהכהנים זריזים הם ודי להם במה שצוה אותם כמו שפירשתי כבר (בתחלת הספר)
@78 **זכור את אשר עשה ה' אלהיך למרים** . אם באת ליזהר שלא תלקה בצרעת לא תספר לשון הרע לשון רש"י ולפי דעתי שהיא מצות עשה ממש כמו זכור את יום השבת לקדשו (שמות כ ח) זכור את היום הזה אשר יצאתם ממצרים (שם יג ג) זכור את אשר עשה לך עמלק (להלן כה יז) כולם מצוה אם כן גם זה כמותם והיא אזהרה מלדבר לשון הרע יצוה במצות עשה שנזכור העונש הגדול שעשה ה' לצדקת הנביאה שלא דברה אלא באחיה גמול חסדה אשר אהבתו כנפשה ולא דברה בפניו שיבוש ולא בפני רבים רק בינה לבין אחיה הקדוש בצנעה וכל מעשיה הטובים לא הועילוה גם אתה אם תשב באחיך תדבר בבן אמך תתן דופי לא תנצל ולשון ספרא (בחקותי פרשה א ב ג) כשהוא אומר ולא תעשו את כל המצות האלה (ויקרא כו יד) הרי מה שכתוב בתורה אמור אם כן למה נאמר ואם לא תשמעו לי להיות עמלים בתורה וכן הוא אומר זכור את יום השבת לקדשו יכול בלבך כשהוא אומר שמור הרי שמירת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך וכן הוא אומר זכור אל תשכח וגו' וכן הוא אומר זכור את אשר עשה ה' אלהיך למרים יכול בלבך כשהוא אומר השמר בנגע הצרעת לשמר מאד ולעשות (פסוק ח) הרי שמירת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך וכן הוא אומר זכור את אשר עשה לך עמלק יכול בלבך כשהוא אומר לא תשכח הרי שכחת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך ופירושה כי אצלם השמר בנגע הצרעת מנגע הצרעת לשמר מאד שלא תבואך ולעשות בה ככל אשר יורו אתכם הכהנים ו זכור את אשר עשה ה' אלהיך למרים שתהא מזכיר זה בפה תמיד ומכאן נראה שרבותינו יעשו אותה מצוה לא ספור ועצה בלבד להנצל מן הנגעים ואיך יתכן שלשון הרע שהוא שקול כשפיכות דמים לא תהיה בו בתורה לא תעשה גמור או לאו הבא מכלל עשה אבל בכתוב הזה אזהרה גדולה בו להמנע ממנו בין בגלוי בין בסתר בין במתכוין להזיק ולהבזות בין שאין מתכוין להזיק כלל וזו מצוה מכלל תרי"ג מצות ושכחה בעל הלכות גדולות וכל המונים המצות אחריו
@81 **ואם איש עני הוא** . יקרא עני כאשר אין לו עבוט אחר כיוצא בו הא אלו היו לו שני כלים מאותו המין נוטל אחד ומחזיר אחד בין שהוא עני או עשיר בנכסים רבים
@83 **לא תעשק שכיר עני ואביון** . ידבר הכתוב בהוה שהעניים והאביונים והגרים משכירים עצמם וכן אם כסף תלוה את עמי את העני עמך (שמות כב כד) וכן לגר ליתום ולאלמנה יהיה (להלן פסוק יט) שהם העניים ברוב וכן בהרבה מקומות ידבר בהוה כמו לא תחסם שור בדישו (להלן כה ד) לא תחרש בשור ובחמור יחדיו (לעיל כב י) ובספרי (תצא קמה) אמרו אם כן למה נאמר עני ואביון ממהר אני ליפרע על ידי עני ואביון יותר מכל אדם ודרשו מגרך זה גר צדק לעבור עליו בשני לאוין
@84 **וטעם ביומו תתן שכרו ולא תבוא עליו השמש** . על דרך הפשט ביאור ממה שנאמר בתורה (ויקרא יט יג) לא תלין פעולת שכיר אתך עד בקר כי דרך הכתובים לדבר בהוה והמנהג לשכור הפועל ביום אחד ולערב הוא יוצא טרם בא השמש ויצוה הכתוב לפרעו ביומו בהשלים מלאכתו מיד ושלא תבוא עליו השמש כדי שיקנה בשכרו לו ולאשתו ולבניו מה שיאכלו בלילה כי עני הוא כרובי הנשכרים ואל השכר הזה הוא נושא נפשו שיקנה בו מזון להחיות נפשו ילמד אותנו בכאן כי מה שאמר בתורה לא תלין פעולת שכיר אתך עד בקר הכונה בו שתפרענו ביומו שאם לא תפרענו בצאתו ממלאכתו מיד הנה ילך לביתו וישאר שכרו אתך עד בקר וימות הוא ברעב בלילה וכן כי היא כסותה לבדה היא שמלתו לעורו במה ישכב (שמות כב כו) יזכיר טעם המצוה ברובי הלאוין ורבותינו פירשו (ב"מ קי) כי הכתוב בתורה "עד בקר" בשכיר יום ושב לבאר בכאן דין שכיר לילה והנה לכל אחד זמן לפרעון שנים עשר שעות והוא האמת בקבלה והנאות בטעם נכון
@87 **וזכרת כי עבד היית** . על מנת כן פדיתיך לשמור חקותי אפילו בדבר שיש בו חסרון כיס לשון רש"י והנכון שהוא חוזר על אזהרת הגר וכבר פירשתי טעמו (שמות כב כ)
@92 **כי יהיה ריב בין אנשים** . על דרך קבלת רבותינו (מכות יג) שהמלקות הוא בחייבי הלאוין מה ענין לו בריב אשר בין שני האנשים האוכל נבלה בביתו לוקה וכן הזורע שדהו או כרמו כלאים והבא על אחת מהנשים האסורות בלאו וכל שאר הלאוין ועוד מה טעם והצדיקו את הצדיק לפיכך דרשוהו בעדים זוממין (שם ב) יאמר הכתוב כי כאשר יהיה ריב בין שני אנשים ונגשו אל המשפט ושפטום על פי שני עדים כאשר נצטוו ואחרי כן יצדיקו את הצדיק וירשיעו את הרשע שלא כמשפט הראשון והיה אם בן הכות הרשע שלא נוכל לקיים בו ועשיתם לו כאשר זמם לעשות לאחיו ויהיה זה כגון שהעידו עליו שהוא בן גרושה או עבד או ממזר או שהעידו עליו שעבר על אחד מן הלאוין ילקה ארבעים ויתכן שיהיה ריב בין אנשים וילקה בו כגון שחבל בו בפחות משוה פרוטה או שקלל חבירו בשם או שמשכן אותו בדברים שעושים בהם אוכל נפש וכיוצא בהם ודבר הכתוב בהווה כי בעל הריב יגישנו לבית דין ועל ידו ילקה וטעם הארבעים כפי מדרשו (תנחומא ישן במדבר כח) לפי שעבר על התורה שנתנה בארבעים יום וגרם מיתה לעצמו שנוצר לארבעים יום ילקה ארבעים ויצא ידי עונשין ענין היבום וסודו והחליצה וטעמה כבר הזכרתים (בראשית לח ח)
@97 **וטעם והיה הבכור אשר תלד יקום על שם אחיו המת** . איננו כפשוטו שיקראו הבן הראשון בשם המת ראובן או שמעון כמוהו שהרי בבעז נאמר כן (רות ד י) ולא יכרת שם המת מעם אחיו ומשער מקומו ולא קראו אותו מחלון אבל הכתוב הזה על דרך האמת הבטחה והנה הוא כפשוטו וסמכו בו רבותינו (ספרי קנו יבמות כד) מדרש שיהא גדול האחים מיבם ושהאילונית אינה מתיבמת וכן אשת הסריס ששמו מחוי וזה כולו אסמכתא כי האילונית ואשת הסריס מגופיה דקרא נפקי
@108 **זכור את אשר עשה לך עמלק** . כבר הזכרתי (לעיל כד ט) המדרש שדרשו בו בספרא (בחקותי פרשה א ג) יכול בלבך כשהוא אומר לא תשכח הרי שכחת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך וכן בספרי (תצא קסו) זכור את אשר עשה לך עמלק בפה לא תשכח בלב ולא ידעתי מה היא הזכירה הזו בפה אם לאמר שנקרא פרשת עמלק בציבור ונמצינו למדין מן התורה בשניה זכור (מגילה כט) ויהיה סמך למקרא מגלה מן התורה והנכון בעיני שהוא לומר שלא תשכח מה שעשה לנו עמלק עד שנמחה את שמו מתחת השמים ונספר זה לבנינו ולדורותינו לומר להם כך עשה לנו הרשע ולכך נצטוינו למחות את שמו וכן במעשה מרים נצטוינו להודיעו לבנינו ולספר בו לדורות ואע"פ שהיה ראוי גם להסתירו שלא לדבר בגנותן של צדיקים אבל צוה הכתוב להודיעו ולגלותו כדי שתהא אזהרת לשון הרע שומה בפיהם מפני שהוא חטא גדול וגורם רעות רבות ובני אדם נכשלים בו תמיד כמו שאמרו (ב"ב קסה) והכל באבק לשון הרע
